  ('3a90b546-05aa-4e6b-8c82-9e31332df378', 'SEC', '08cfccc3-991a-49c2-b522-1dc0681ec39d', '1', 'Firearm Violence Prevention Act Part 1 s. 1', 'Definitions', 'In this Act:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7fb6a3ec-848b-46e2-b54b-4111f6742603', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'adult', '"adult" means an individual who is 18 years of age or older;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6dd61440-dce4-46d7-9242-dbe42b3e0e90', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'ammunition', '"ammunition", in relation to a firearm, means prohibited ammunition or any other shot, bullet or projectile designed to be discharged from the firearm;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('56c9cb90-4265-45a9-ae50-cb21460e4558', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'boat', '"boat" means a vessel or other craft in, on or by which a person or thing may be transported or drawn on water;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cd97df10-4e69-49f2-8a08-48bbe65bffb3', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'cartridge magazine', '"cartridge magazine" means a device or container from which ammunition may be fed into the firing chamber of a firearm;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('de8e4a55-7380-4f5c-9880-edbd63eb72b0', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'federal Act', '"federal Act" means the Firearms Act (Canada);', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d485e384-da44-4e9b-a792-7824cfa7ec9e', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'federal licence', '"federal licence" means a licence issued under the federal Act;', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f7a9eb86-ea16-4a66-91f9-e7678225707e', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'firearm', '"firearm" has the same meaning as in section 2 of the Criminal Code;', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
