  ('5cb277d1-577f-432d-9c5a-3335ad6ee42a', 'DEF', '3a90b546-05aa-4e6b-8c82-9e31332df378', NULL, 'Firearm Violence Prevention Act Part 1 s. 1', 'loaded', '"loaded", in relation to a firearm, means ammunition is in any of the following:', 9, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
