  ('401799b8-34df-4b3d-9c50-0c4abaed1934', 'PAR', '5cb277d1-577f-432d-9c5a-3335ad6ee42a', 'c', 'Firearm Violence Prevention Act Part 1 s. 1 (c)', NULL, 'a cartridge magazine that is attached to a hinged floor plate of the firearm;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
