  ('67c7c587-f538-47bd-b266-98e3e53a1d92', 'PAR', '5cb277d1-577f-432d-9c5a-3335ad6ee42a', 'e', 'Firearm Violence Prevention Act Part 1 s. 1 (e)', NULL, 'a prescribed part of', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
