  ('07640ee1-2a55-45a0-bc17-a7aa08f603fe', 'PART', 'da8abd55-5ee1-4c9d-9cb3-be977df3b081', '2', 'Firearm Violence Prevention Act Part 2', 'Firearms and Imitation Firearms', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', 'DIV', '07640ee1-2a55-45a0-bc17-a7aa08f603fe', '1', 'Firearm Violence Prevention Act Part 2 Division 1', 'General Prohibitions and Requirements Respecting Firearms and Imitation Firearms', NULL, 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3a47746d-eb8b-4b4d-8f6d-a48b5d60109e', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '3', 'Firearm Violence Prevention Act Part 2 Division 1 s. 3', 'Prohibition against using, transporting, carrying or storing firearm in unsafe manner', 'A person must not use, transport, carry or store a firearm in a manner that', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8d4fe17c-661c-4af8-a32f-f2c92d78d724', 'PAR', '3a47746d-eb8b-4b4d-8f6d-a48b5d60109e', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 3 (a)', NULL, 'poses a risk to the life or safety of an individual, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7ab7f829-a2ac-4877-afb3-c06e1acd1d39', 'PAR', '3a47746d-eb8b-4b4d-8f6d-a48b5d60109e', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 3 (b)', NULL, 'poses a risk of damage to property.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('19484b55-e628-4580-9e4f-17b739fb0cd6', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '4', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4', 'Prohibition and requirement respecting firearm or imitation firearm in vehicle or boat', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('08bcb60c-f498-408e-acde-ad0527b4658f', 'SUBSEC', '19484b55-e628-4580-9e4f-17b739fb0cd6', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (1)', NULL, 'A person must not transport, carry or store a loaded firearm in or on a vehicle or boat.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5cb0319d-53f7-4599-8bcd-71466a2e7e85', 'SUBSEC', '19484b55-e628-4580-9e4f-17b739fb0cd6', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (2)', NULL, 'A person who is transporting, carrying or storing a low-velocity firearm or imitation firearm in or on a vehicle or boat must transport, carry or store the low-velocity firearm or imitation firearm in accordance with the regulations.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6e4d2dff-ea82-4cec-afef-b722161c3b48', 'SUBSEC', '19484b55-e628-4580-9e4f-17b739fb0cd6', '3', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (3)', NULL, 'For certainty, for the purposes of subsection (1), a firearm is loaded even if the firearm is temporarily incapable of being discharged.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2813a4f5-5d1b-4618-a847-6b6ced9fad9c', 'SUBSEC', '19484b55-e628-4580-9e4f-17b739fb0cd6', '4', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (4)', NULL, 'For certainty, for the purposes of subsection (1), a muzzle-loaded firearm is loaded if all of the following apply:', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1754be80-1d06-468e-b9a6-2bf4cab1fe7b', 'PAR', '2813a4f5-5d1b-4618-a847-6b6ced9fad9c', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (4) (a)', NULL, 'a firing cap or flint is inside or attached to the firearm;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2a4b5ee8-d7b7-48ce-ab66-1cc41aa75052', 'PAR', '2813a4f5-5d1b-4618-a847-6b6ced9fad9c', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (4) (b)', NULL, 'a powder charge is in the barrel or cylinder of the firearm;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('04390228-004e-4914-a892-7157fbb14744', 'PAR', '2813a4f5-5d1b-4618-a847-6b6ced9fad9c', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 4 (4) (c)', NULL, 'the firearm is primed to discharge.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6d9b9415-e79d-40da-bcdc-486f94da29e6', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '5', 'Firearm Violence Prevention Act Part 2 Division 1 s. 5', 'Prohibition against discharging firearm from vehicle or boat', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6bf9a0cf-7a1f-4992-bc25-530518299674', 'SUBSEC', '6d9b9415-e79d-40da-bcdc-486f94da29e6', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 5 (1)', NULL, 'A person must not discharge a firearm in, on or from a vehicle or boat.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('31d1b0e4-018d-4394-a445-669c68e394fe', 'SUBSEC', '6d9b9415-e79d-40da-bcdc-486f94da29e6', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 5 (2)', NULL, 'For certainty, this section must be construed in accordance with section 35 of the Constitution Act, 1982.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0455e6a0-75d1-43c8-8de5-a69d795dc036', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '6', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6', 'Prohibition against operating vehicle if certain firearms, ammunition or devices in vehicle', NULL, 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('351568e3-5d07-49c2-b7d7-05b4969ffe5d', 'SUBSEC', '0455e6a0-75d1-43c8-8de5-a69d795dc036', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (1)', NULL, 'Despite the definition of "vehicle" in section 1 [definitions], in this section, "vehicle" does not include any of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1b6ce686-0608-495c-9b0a-9c10b8b1369d', 'PAR', '351568e3-5d07-49c2-b7d7-05b4969ffe5d', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (1) (a)', NULL, 'a device used exclusively on stationary rails or tracks in, on or by which a person or thing is or may be transported;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8d779abb-df5d-4df0-854b-f2796412ecc9', 'PAR', '351568e3-5d07-49c2-b7d7-05b4969ffe5d', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (1) (b)', NULL, 'a prescribed vehicle, machine or device.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('99affc3b-2e12-40c5-8444-17abf99e1b87', 'SUBSEC', '0455e6a0-75d1-43c8-8de5-a69d795dc036', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (2)', NULL, 'A person must not operate a vehicle if any of the following is in or on the vehicle:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6f56c28f-99b5-42ef-8558-04d8c25fc9f5', 'PAR', '99affc3b-2e12-40c5-8444-17abf99e1b87', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (2) (a)', NULL, 'a non-restricted firearm, prohibited firearm or restricted firearm;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2ad292a7-dee6-4056-939f-7d641588fe0c', 'PAR', '99affc3b-2e12-40c5-8444-17abf99e1b87', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (2) (b)', NULL, 'prohibited ammunition;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('848246d1-494b-45d0-9174-294c55de4ffc', 'PAR', '99affc3b-2e12-40c5-8444-17abf99e1b87', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (2) (c)', NULL, 'a prohibited device.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7acdf45b-013a-4b1d-a7dc-e490a4bd4f02', 'SUBSEC', '0455e6a0-75d1-43c8-8de5-a69d795dc036', '3', 'Firearm Violence Prevention Act Part 2 Division 1 s. 6 (3)', NULL, 'If any firearm, ammunition or device referred to in subsection (2) is in or on a vehicle, a person who operates the vehicle contravenes subsection (2) whether or not the vehicle is in motion.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d60c55cd-ae86-4ffc-81f3-ea2bf7810a5c', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '7', 'Firearm Violence Prevention Act Part 2 Division 1 s. 7', 'Exemption if certain firearms, ammunition or devices authorized under federal Act', 'A person does not contravene section 6 (2) if, in respect of the non-restricted firearm, prohibited firearm, restricted firearm, prohibited ammunition or prohibited device that is in or on the vehicle,', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2c6e0eda-a8e3-429b-aa43-dfb3d4b281e0', 'PAR', 'd60c55cd-ae86-4ffc-81f3-ea2bf7810a5c', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 7 (a)', NULL, 'the person or another occupant of the vehicle is authorized under the federal Act to possess the firearm, ammunition or device,', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('00e07b85-1e26-4a18-85b2-8fdffa9dcd4a', 'PAR', 'd60c55cd-ae86-4ffc-81f3-ea2bf7810a5c', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 7 (b)', NULL, 'in the case of a prohibited firearm or restricted firearm that is in or on the vehicle, the person or another occupant of the vehicle is authorized under the federal Act to transport and, if applicable, carry the firearm, and', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a88575d4-bdce-4cb2-9cfe-5bfe8ca901c7', 'PAR', 'd60c55cd-ae86-4ffc-81f3-ea2bf7810a5c', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 7 (c)', NULL, 'the firearm, ammunition or device is being transported, carried or stored in a manner that complies with requirements under the federal Act.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('333de1a8-12f0-453b-b72c-6531830fdfbc', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '8', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8', 'Prohibition against causing public disturbance with low-velocity firearm or imitation firearm', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ee22f44f-95b2-4ec6-9962-4c805227f337', 'SUBSEC', '333de1a8-12f0-453b-b72c-6531830fdfbc', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (1)', NULL, 'In this section, "public place" means', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('90942fb6-78d3-49ea-a391-18717b919030', 'PAR', 'ee22f44f-95b2-4ec6-9962-4c805227f337', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (1) (a)', NULL, 'any place to which the public has access as of right or by invitation, express or implied, whether or not a fee is charged for entry, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5d061432-022a-4d4e-9ed5-54b4b1281eb2', 'PAR', 'ee22f44f-95b2-4ec6-9962-4c805227f337', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (1) (b)', NULL, 'any vehicle or boat located in', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('85251cb3-d2e8-41c1-871f-d2c57432acdb', 'SUBPAR', '5d061432-022a-4d4e-9ed5-54b4b1281eb2', 'i', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (1) (b) (i)', NULL, 'a place referred to in paragraph (a), or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d19ae5cc-d15b-4b84-847e-38fdce1820ca', 'SUBPAR', '5d061432-022a-4d4e-9ed5-54b4b1281eb2', 'ii', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (1) (b) (ii)', NULL, 'any outdoor place open to public view.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('dca90dc0-a8cf-47fe-8710-10020e6fbe88', 'SUBSEC', '333de1a8-12f0-453b-b72c-6531830fdfbc', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 8 (2)', NULL, 'A person must not use, carry or store a low-velocity firearm or imitation firearm in a manner that causes or is likely to cause a disturbance in a public place.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('970e8111-29df-407c-8357-499f4f24e6f2', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '9', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9', 'Prohibition against possessing low-velocity firearm or imitation firearm if subject to federal prohibition', NULL, 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c1dbd5aa-2ef3-47e6-bec5-bc5babcf5b8e', 'SUBSEC', '970e8111-29df-407c-8357-499f4f24e6f2', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (1)', NULL, 'Despite the definition of "ammunition" in section 1 [definitions], in subsection (2) (e) of this section, "ammunition" has the same meaning as in section 84 (1) of the Criminal Code.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('37d81760-21e8-4a09-af3b-b2624e7c82b0', 'SUBSEC', '970e8111-29df-407c-8357-499f4f24e6f2', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2)', NULL, 'A person must not possess a low-velocity firearm or imitation firearm if, by order under the Criminal Code or the Youth Criminal Justice Act (Canada), the person is prohibited from possessing any of the following:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('72cc3e98-c844-415a-8e00-12e1d9a8350e', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (a)', NULL, 'a non-restricted firearm, prohibited firearm or restricted firearm;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e657a07e-6cbc-436b-919a-f0d241f2f89a', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (b)', NULL, 'a cross-bow within the meaning of section 84 (1) of the Criminal Code;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('bdfa58f2-777f-4b84-9076-f587fd842a5d', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (c)', NULL, 'a prohibited weapon or restricted weapon within the meaning of section 84 (1) of the Criminal Code;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('65533687-47da-43aa-b705-7edd56bc65bc', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'd', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (d)', NULL, 'a prohibited device;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e86bbcbc-728a-4a50-922e-fa36002b6454', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'e', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (e)', NULL, 'ammunition or prohibited ammunition;', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b93d7371-4eab-479f-8ae1-0083a4f40f86', 'PAR', '37d81760-21e8-4a09-af3b-b2624e7c82b0', 'f', 'Firearm Violence Prevention Act Part 2 Division 1 s. 9 (2) (f)', NULL, 'an explosive substance within the meaning of section 2 of the Criminal Code.', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('075797a4-efff-496b-87a6-45a7ccf77262', 'SEC', 'cd6977d1-0ce7-425a-8ffe-6ab7f7bd5606', '10', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10', 'Exemptions for designated officials and prescribed exemptions', NULL, 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a310b574-ca76-487c-ace7-50d368bd2cab', 'SUBSEC', '075797a4-efff-496b-87a6-45a7ccf77262', '1', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1)', NULL, 'In this section:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'DEF', 'a310b574-ca76-487c-ace7-50d368bd2cab', NULL, 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1)', 'designated official', '"designated official" means an individual who is any of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ef229aa1-1d08-4953-8eb9-d2032004d4f6', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (a)', NULL, 'a peace officer, other than a mayor, as described in paragraph (a), (b) or (c) of the definition of "peace officer" in section 29 [expressions defined] of the Interpretation Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9e32089a-1efd-4a51-b6f1-0cfe9a6b45f3', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (b)', NULL, 'a conservation officer within the meaning of section 1 (1) [definitions] of the Environmental Management Act;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3978d593-dd9e-4fc8-83d6-97019b6d57a6', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (c)', NULL, 'a wildlife officer;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('465debc5-7cc4-4078-a766-1edf1f63eec2', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'd', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (d)', NULL, 'a park officer or park ranger within the meaning of section 1 [definitions] of the Park Act;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ef4f7c7f-1b64-40b1-ae4d-3818bb87135d', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'e', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (e)', NULL, 'an employee of an armoured car guard service within the meaning of section 1 [definitions] of the Security Services Act;', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('51a73570-381b-4c71-994a-62bf05f5a065', 'PAR', 'bb501267-7d38-42bd-a2f1-4f22cf97eeae', 'f', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (f)', NULL, 'a prescribed person;', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8abc53cc-6933-432d-92a8-d1fa63337577', 'DEF', 'a310b574-ca76-487c-ace7-50d368bd2cab', NULL, 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1)', 'wildlife officer', '"wildlife officer" means an individual who is any of the following:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2cd127f9-d194-4a65-9da2-bb60cc683a61', 'PAR', '8abc53cc-6933-432d-92a8-d1fa63337577', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (a)', NULL, 'an assistant director, director or regional manager within the meaning of section 1 (1) [definitions and interpretation] of the Wildlife Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ce367bf2-8fdf-45b8-9a2d-2a7cbb299c28', 'PAR', '8abc53cc-6933-432d-92a8-d1fa63337577', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (1) (b)', NULL, 'a prescribed officer or employee of the government.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('14e6d7c9-f5ee-480d-b866-63016555b67a', 'SUBSEC', '075797a4-efff-496b-87a6-45a7ccf77262', '2', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2)', NULL, 'A designated official who carries out an action that would otherwise contravene any of the following provisions does not contravene the provision if the action is lawful for the purposes of exercising the designated official''s powers or performing the designated official''s duties:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('13ce331a-2b24-442d-8cf4-3b80f8b5deca', 'PAR', '14e6d7c9-f5ee-480d-b866-63016555b67a', 'a', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2) (a)', NULL, 'section 3 [prohibition against using, transporting, carrying or storing firearm in unsafe manner];', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('70d74ed9-401a-4b0b-aedf-5fb6de08c1da', 'PAR', '14e6d7c9-f5ee-480d-b866-63016555b67a', 'b', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2) (b)', NULL, 'section 4 (1) or (2) [prohibition and requirement respecting firearm or imitation firearm in vehicle or boat];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('112f07db-f116-4bd0-9a16-8d533d868ae3', 'PAR', '14e6d7c9-f5ee-480d-b866-63016555b67a', 'c', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2) (c)', NULL, 'section 5 (1) [prohibition against discharging firearm from vehicle or boat];', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c4475b1c-4863-4778-b6c6-11fd23e4f8ed', 'PAR', '14e6d7c9-f5ee-480d-b866-63016555b67a', 'd', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2) (d)', NULL, 'section 6 (2) [prohibition against operating vehicle if certain firearms, ammunition or devices in vehicle];', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2a165c42-7f3c-4e32-8919-56f1348cf97b', 'PAR', '14e6d7c9-f5ee-480d-b866-63016555b67a', 'e', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (2) (e)', NULL, 'section 8 (2) [prohibition against causing public disturbance with low-velocity firearm or imitation firearm].', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e5107eaf-8629-44f8-8bdf-0364a61c2546', 'SUBSEC', '075797a4-efff-496b-87a6-45a7ccf77262', '3', 'Firearm Violence Prevention Act Part 2 Division 1 s. 10 (3)', NULL, 'The regulations may establish exemptions in relation to a prohibition or requirement under section 3, 4, 5 (1), 6 (2), 8 (2) or 9 (2).', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('287de11b-c1e6-406a-a85b-fc651b8b91f1', 'DIV', '07640ee1-2a55-45a0-bc17-a7aa08f603fe', '2', 'Firearm Violence Prevention Act Part 2 Division 2', 'Prohibitions and Requirements Respecting Minors and Low-Velocity Firearms and Imitation Firearms', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2172d36a-ff72-473e-b081-57bf0b92af23', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '11', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11', 'Prohibition against selling, renting or supplying low-velocity firearm, imitation firearm or ammunition to minor', NULL, 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ac456f76-65e4-43da-a84b-689d10ac5827', 'SUBSEC', '2172d36a-ff72-473e-b081-57bf0b92af23', '1', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (1)', NULL, 'A person must not sell or offer to sell a low-velocity firearm or imitation firearm to a minor.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('470d8a9f-48ab-421c-90c4-058600b4e241', 'SUBSEC', '2172d36a-ff72-473e-b081-57bf0b92af23', '2', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (2)', NULL, 'A person must not sell or offer to sell ammunition for a low-velocity firearm to a minor.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c7fd2157-b51d-4ae3-83a2-2da15e7952d6', 'SUBSEC', '2172d36a-ff72-473e-b081-57bf0b92af23', '3', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (3)', NULL, 'A person must not rent or offer to rent, or supply or offer to supply, for consideration, any of the following to a minor:', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('99aab77b-bd9c-4641-99b4-c06756312642', 'PAR', 'c7fd2157-b51d-4ae3-83a2-2da15e7952d6', 'a', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (3) (a)', NULL, 'a low-velocity firearm;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ab4078df-81cd-44fe-b941-bd297e8f7761', 'PAR', 'c7fd2157-b51d-4ae3-83a2-2da15e7952d6', 'b', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (3) (b)', NULL, 'an imitation firearm;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5685a41b-c282-4045-a84d-8ce3aac5dd08', 'PAR', 'c7fd2157-b51d-4ae3-83a2-2da15e7952d6', 'c', 'Firearm Violence Prevention Act Part 2 Division 2 s. 11 (3) (c)', NULL, 'ammunition for a low-velocity firearm.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('59bbb145-0fdd-4d35-99e9-18dc3d66f9ba', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '12', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12', 'Exemption if minor produces credible false identification or false federal licence', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a89ba2f6-0d40-46b2-aca8-98603e822f2c', 'SUBSEC', '59bbb145-0fdd-4d35-99e9-18dc3d66f9ba', '1', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (1)', NULL, 'A person does not contravene section 11 (1), (2) or (3) if', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d073fc54-91b7-464f-8df2-5c812ae39f2c', 'PAR', 'a89ba2f6-0d40-46b2-aca8-98603e822f2c', 'a', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (1) (a)', NULL, 'at the person''s request, the minor produces prescribed identification, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8c4e79e8-2f3d-4c2a-bb19-0377a1be229e', 'PAR', 'a89ba2f6-0d40-46b2-aca8-98603e822f2c', 'b', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (1) (b)', NULL, 'after examining the prescribed identification produced by the minor, the person reasonably believes that', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f2a9dbc1-fa7c-4001-87d9-8dceb6035e62', 'SUBPAR', '8c4e79e8-2f3d-4c2a-bb19-0377a1be229e', 'i', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (1) (b) (i)', NULL, 'the identification is authentic, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1dcff3c2-7bcf-4c0d-93d6-d1a5ea46ab40', 'SUBPAR', '8c4e79e8-2f3d-4c2a-bb19-0377a1be229e', 'ii', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (1) (b) (ii)', NULL, 'the minor is an adult.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('89ac953f-df7f-4122-a08e-5772c5ee15a3', 'SUBSEC', '59bbb145-0fdd-4d35-99e9-18dc3d66f9ba', '2', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (2)', NULL, 'A person does not contravene section 11 (1), (2) or (3) if', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ce2ce5fd-2f4c-49bf-aeba-460256aeacd7', 'PAR', '89ac953f-df7f-4122-a08e-5772c5ee15a3', 'a', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (2) (a)', NULL, 'the minor produces to the person a federal licence, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2c2b45d9-67fb-4d2a-83a4-5fcd59f54959', 'PAR', '89ac953f-df7f-4122-a08e-5772c5ee15a3', 'b', 'Firearm Violence Prevention Act Part 2 Division 2 s. 12 (2) (b)', NULL, 'after examining the federal licence produced by the minor, the person reasonably believes that the minor is authorized to possess firearms under that federal licence.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ea5615fe-d3c4-4fd2-b619-16fa697dbc59', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '13', 'Firearm Violence Prevention Act Part 2 Division 2 s. 13', 'Exemption for certain sporting or recreational facilities', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9aadc5b4-784b-4afd-b700-5214a642b44f', 'SUBSEC', 'ea5615fe-d3c4-4fd2-b619-16fa697dbc59', '1', 'Firearm Violence Prevention Act Part 2 Division 2 s. 13 (1)', NULL, 'A person who operates a facility that provides sporting or recreational activities involving the use of low-velocity firearms does not contravene section 11 (2) or (3) (a) or (c) [prohibition against selling, renting or supplying low-velocity firearm, imitation firearm or ammunition to minor] if,', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('663e8ef2-a37d-40d9-a64a-1b814d1a6951', 'PAR', '9aadc5b4-784b-4afd-b700-5214a642b44f', 'a', 'Firearm Violence Prevention Act Part 2 Division 2 s. 13 (1) (a)', NULL, 'in the case of section 11 (2) or (3) (c), the minor will be using the ammunition in or on the premises of the facility, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('48e0bdc1-7aee-4830-8c52-8383bdfae9bb', 'PAR', '9aadc5b4-784b-4afd-b700-5214a642b44f', 'b', 'Firearm Violence Prevention Act Part 2 Division 2 s. 13 (1) (b)', NULL, 'in the case of section 11 (3) (a), the minor will be using the low-velocity firearm only in or on the premises of the facility.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c387b9d9-3aa7-46ee-bf70-c849746751c5', 'SUBSEC', 'ea5615fe-d3c4-4fd2-b619-16fa697dbc59', '2', 'Firearm Violence Prevention Act Part 2 Division 2 s. 13 (2)', NULL, 'A person who operates a facility that provides sporting or recreational activities involving the use of imitation firearms does not contravene section 11 (3) (b) if the minor will be using the imitation firearm only in or on the premises of the facility.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9cfcf1ba-96f2-423c-9182-734ee92ccb74', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '14', 'Firearm Violence Prevention Act Part 2 Division 2 s. 14', 'Prohibition against minor transporting, carrying or storing low-velocity firearm or imitation firearm', NULL, 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('63d74cc7-e256-4f0a-a5af-d23ec319edf5', 'SUBSEC', '9cfcf1ba-96f2-423c-9182-734ee92ccb74', '1', 'Firearm Violence Prevention Act Part 2 Division 2 s. 14 (1)', NULL, 'A minor must not transport, carry or store a loaded low-velocity firearm.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d12ebf88-079c-4181-bd1b-c7cb1fea475f', 'SUBSEC', '9cfcf1ba-96f2-423c-9182-734ee92ccb74', '2', 'Firearm Violence Prevention Act Part 2 Division 2 s. 14 (2)', NULL, 'A minor who is transporting, carrying or storing a low-velocity firearm or imitation firearm must transport, carry or store the low-velocity firearm or imitation firearm inside an opaque container that is locked.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0019d2b5-8f81-4e9b-a503-501c3796c8d2', 'SUBSEC', '9cfcf1ba-96f2-423c-9182-734ee92ccb74', '3', 'Firearm Violence Prevention Act Part 2 Division 2 s. 14 (3)', NULL, 'If a minor is transporting, carrying or storing a low-velocity firearm or imitation firearm in or on a vehicle or boat, section 4 [prohibition and requirement respecting firearm or imitation firearm in vehicle or boat] applies instead of this section.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8fcabaac-3f5e-4a0c-807a-3cf49986acc2', 'SUBSEC', '9cfcf1ba-96f2-423c-9182-734ee92ccb74', '4', 'Firearm Violence Prevention Act Part 2 Division 2 s. 14 (4)', NULL, 'For certainty, for the purposes of subsection (1), a low-velocity firearm is loaded even if the low-velocity firearm is temporarily incapable of being discharged.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ae0496f2-be1c-4e01-a6c6-82f54301e8e8', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '15', 'Firearm Violence Prevention Act Part 2 Division 2 s. 15', 'Prohibition against minor discharging or possessing low-velocity firearm or imitation firearm in prohibited area', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('aca2f361-09d8-4453-8bc5-e53dafe10e95', 'SUBSEC', 'ae0496f2-be1c-4e01-a6c6-82f54301e8e8', '1', 'Firearm Violence Prevention Act Part 2 Division 2 s. 15 (1)', NULL, 'In this section, "prohibited area" means an area where the discharge of a firearm or imitation firearm is prohibited under a law in force in British Columbia.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('48b85d0e-6415-4d2e-956e-c87bcc507478', 'SUBSEC', 'ae0496f2-be1c-4e01-a6c6-82f54301e8e8', '2', 'Firearm Violence Prevention Act Part 2 Division 2 s. 15 (2)', NULL, 'A minor must not discharge a low-velocity firearm or imitation firearm in a prohibited area.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('320c6358-062f-492b-be61-43232a5e4897', 'SUBSEC', 'ae0496f2-be1c-4e01-a6c6-82f54301e8e8', '3', 'Firearm Violence Prevention Act Part 2 Division 2 s. 15 (3)', NULL, 'A minor must not possess a low-velocity firearm or imitation firearm in a prohibited area unless the low-velocity firearm or imitation firearm is being transported, carried and stored in compliance with section 4 [prohibition and requirement respecting firearm or imitation firearm in vehicle or boat] or 14, as applicable.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8c9d0cab-b536-4065-87d6-11523b035417', 'SEC', '287de11b-c1e6-406a-a85b-fc651b8b91f1', '16', 'Firearm Violence Prevention Act Part 2 Division 2 s. 16', 'Prescribed exemptions in relation to prohibitions and requirements respecting minors', 'The regulations may establish exemptions in relation to a prohibition or requirement under any of the following provisions:', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('30c1f361-e464-4588-b3dd-4e54e9f5dcd8', 'PAR', '8c9d0cab-b536-4065-87d6-11523b035417', 'a', 'Firearm Violence Prevention Act Part 2 Division 2 s. 16 (a)', NULL, 'section 11 [prohibition against selling, renting or supplying low-velocity firearm, imitation firearm or ammunition to minor];', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('08e8bfc4-4589-4755-86dd-b920c7aa446c', 'PAR', '8c9d0cab-b536-4065-87d6-11523b035417', 'b', 'Firearm Violence Prevention Act Part 2 Division 2 s. 16 (b)', NULL, 'section 14 [prohibition against minor transporting, carrying or storing low-velocity firearm or imitation firearm];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('141ef178-9ac7-4c27-b816-19d88692b6f4', 'PAR', '8c9d0cab-b536-4065-87d6-11523b035417', 'c', 'Firearm Violence Prevention Act Part 2 Division 2 s. 16 (c)', NULL, 'section 15.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('63c8aad0-55af-4bb1-9c47-b689e0edb942', 'PART', 'da8abd55-5ee1-4c9d-9cb3-be977df3b081', '3', 'Firearm Violence Prevention Act Part 3', 'Designated Property', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4d445b97-013d-428a-bc50-74e2a8cc6cee', 'SEC', '63c8aad0-55af-4bb1-9c47-b689e0edb942', '17', 'Firearm Violence Prevention Act Part 3 s. 17', 'Definitions for Part 3', 'In this Part:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b3469e4a-ed27-42fd-b3c4-aa5c723b8b0f', 'DEF', '4d445b97-013d-428a-bc50-74e2a8cc6cee', NULL, 'Firearm Violence Prevention Act Part 3 s. 17', 'designated property', '"designated property" means a property referred to in section 18;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fa73ccb7-1f47-40af-8b1b-1cab4b19acf0', 'DEF', '4d445b97-013d-428a-bc50-74e2a8cc6cee', NULL, 'Firearm Violence Prevention Act Part 3 s. 17', 'entity', '"entity" means a person, authority, board, institution, organization or other body;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9c17abdb-2206-48cc-a71b-c9b48eab7ee4', 'DEF', '4d445b97-013d-428a-bc50-74e2a8cc6cee', NULL, 'Firearm Violence Prevention Act Part 3 s. 17', 'peace officer', '"peace officer" means either of the following:', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1f29b59d-7f47-4cbb-ac1b-8956d018377c', 'PAR', '9c17abdb-2206-48cc-a71b-c9b48eab7ee4', 'a', 'Firearm Violence Prevention Act Part 3 s. 17 (a)', NULL, 'a peace officer, other than a mayor, as described in paragraph (a), (b) or (c) of the definition of "peace officer" in section 29 [expressions defined] of the Interpretation Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('24dd7f79-64b2-4137-9cc9-39a06af6311b', 'PAR', '9c17abdb-2206-48cc-a71b-c9b48eab7ee4', 'b', 'Firearm Violence Prevention Act Part 3 s. 17 (b)', NULL, 'a prescribed person;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('97ece910-b8dc-4de9-a01c-a30a06ff35f7', 'DEF', '4d445b97-013d-428a-bc50-74e2a8cc6cee', NULL, 'Firearm Violence Prevention Act Part 3 s. 17', 'property', '"property" means real property, buildings or structures.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('aa9bf379-092d-4a4a-b559-5fd6b1643589', 'SEC', '63c8aad0-55af-4bb1-9c47-b689e0edb942', '18', 'Firearm Violence Prevention Act Part 3 s. 18', 'Prohibition against possessing firearm or imitation firearm in or on designated property', 'A person must not possess a firearm or imitation firearm in or on any of the following:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('44302179-932b-4fba-ab34-a8242411ebdc', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'a', 'Firearm Violence Prevention Act Part 3 s. 18 (a)', NULL, 'child care property within the meaning of section 20;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ae432fc1-7598-48be-bf2a-e85e3674a690', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'b', 'Firearm Violence Prevention Act Part 3 s. 18 (b)', NULL, 'court property within the meaning of section 21;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('14fc0c7d-9a47-4a83-8c75-f3113f6bd51c', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'c', 'Firearm Violence Prevention Act Part 3 s. 18 (c)', NULL, 'hospital property within the meaning of section 22;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f10301cf-34bb-43b3-8068-c5752c2e57ab', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'd', 'Firearm Violence Prevention Act Part 3 s. 18 (d)', NULL, 'post-secondary property within the meaning of section 23;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ad28b6c5-1fcb-46df-ada5-8247c3631da4', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'e', 'Firearm Violence Prevention Act Part 3 s. 18 (e)', NULL, 'public worship property within the meaning of section 24;', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('54b35a7c-9c8d-49e4-986c-032932c46b1e', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'f', 'Firearm Violence Prevention Act Part 3 s. 18 (f)', NULL, 'school property within the meaning of section 25;', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ced27b69-7651-4c48-9892-ed5adf56e565', 'PAR', 'aa9bf379-092d-4a4a-b559-5fd6b1643589', 'g', 'Firearm Violence Prevention Act Part 3 s. 18 (g)', NULL, 'property or things designated by regulation as designated property.', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cce5c38d-4879-4647-a031-e9628b7f5822', 'SEC', '63c8aad0-55af-4bb1-9c47-b689e0edb942', '19', 'Firearm Violence Prevention Act Part 3 s. 19', 'Exemptions from prohibitions respecting designated property', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5dcfccb9-e056-4d9b-8605-dfb876467e45', 'SUBSEC', 'cce5c38d-4879-4647-a031-e9628b7f5822', '1', 'Firearm Violence Prevention Act Part 3 s. 19 (1)', NULL, 'A peace officer who possesses a firearm or imitation firearm in or on a designated property does not contravene section 18 if that possession is lawful for the purposes of exercising the peace officer''s powers or performing the peace officer''s duties.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b3f6cefe-bb2e-4f11-bc00-36bc28382834', 'SUBSEC', 'cce5c38d-4879-4647-a031-e9628b7f5822', '2', 'Firearm Violence Prevention Act Part 3 s. 19 (2)', NULL, 'The regulations may establish exemptions in relation to a prohibition under section 18.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e2ae7d1c-7679-412a-91dd-a7c8fc3131d7', 'SEC', '63c8aad0-55af-4bb1-9c47-b689e0edb942', '20', 'Firearm Violence Prevention Act Part 3 s. 20', 'Meaning of "child care property"', NULL, 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8282ab73-735a-4e75-9f67-9829c2cc793f', 'SUBSEC', 'e2ae7d1c-7679-412a-91dd-a7c8fc3131d7', '1', 'Firearm Violence Prevention Act Part 3 s. 20 (1)', NULL, 'In this section, "regulated child care" means child care provided by an entity that holds or is required to hold a licence under the Community Care and Assisted Living Act.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
