  ('d80f98bb-d2fc-4de2-83ad-48f4098850c4', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '27', 'Firearm Violence Prevention Act Part 4 s. 27', 'Duties respecting shooting range records', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
