  ('dd93c283-5c67-4489-86d7-c01a718113d3', 'SUBSEC', 'd80f98bb-d2fc-4de2-83ad-48f4098850c4', '2', 'Firearm Violence Prevention Act Part 4 s. 27 (2)', NULL, 'If a shooting range user is a member of a shooting club, the shooting range records must contain the following information:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('41ecc414-fb42-4686-bf39-e4cd5897a283', 'PAR', 'dd93c283-5c67-4489-86d7-c01a718113d3', 'a', 'Firearm Violence Prevention Act Part 4 s. 27 (2) (a)', NULL, 'the name of the shooting range user;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('60796dc1-24d9-440c-9579-af79ab283d0f', 'PAR', 'dd93c283-5c67-4489-86d7-c01a718113d3', 'b', 'Firearm Violence Prevention Act Part 4 s. 27 (2) (b)', NULL, 'the name of the shooting club;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('62b4a90d-374e-45bc-8cf5-43ec05945315', 'PAR', 'dd93c283-5c67-4489-86d7-c01a718113d3', 'c', 'Firearm Violence Prevention Act Part 4 s. 27 (2) (c)', NULL, 'the membership number of the shooting range user in respect of the shooting club;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b7e2be32-18ef-4758-86f7-7cb9d982f5c5', 'PAR', 'dd93c283-5c67-4489-86d7-c01a718113d3', 'd', 'Firearm Violence Prevention Act Part 4 s. 27 (2) (d)', NULL, 'the dates on which the shooting range is used or has been used by the shooting range user;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c08b3acc-13e7-402d-95bd-027d2e51306c', 'PAR', 'dd93c283-5c67-4489-86d7-c01a718113d3', 'e', 'Firearm Violence Prevention Act Part 4 s. 27 (2) (e)', NULL, 'prescribed information.', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b8eb36af-1274-4c81-add8-31afac0f1b84', 'SUBSEC', 'd80f98bb-d2fc-4de2-83ad-48f4098850c4', '3', 'Firearm Violence Prevention Act Part 4 s. 27 (3)', NULL, 'If a shooting range user is not a member of a shooting club, the shooting range records must contain the following information:', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8cbbdc25-c6ec-4bb8-938b-6875c37263f7', 'PAR', 'b8eb36af-1274-4c81-add8-31afac0f1b84', 'a', 'Firearm Violence Prevention Act Part 4 s. 27 (3) (a)', NULL, 'the name, address and phone number of the shooting range user;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4fd81777-905c-4dbd-bb70-672e4729d972', 'PAR', 'b8eb36af-1274-4c81-add8-31afac0f1b84', 'b', 'Firearm Violence Prevention Act Part 4 s. 27 (3) (b)', NULL, 'if the shooting range user is authorized to possess firearms under a federal licence, the licence number of the federal licence;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('736a6044-eb2e-4b10-9b0b-14d30f422379', 'PAR', 'b8eb36af-1274-4c81-add8-31afac0f1b84', 'c', 'Firearm Violence Prevention Act Part 4 s. 27 (3) (c)', NULL, 'if the shooting range user is not authorized to possess firearms under a federal licence, the date of birth of the shooting range user;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2477fbed-9e6d-447b-877d-773d948b8e37', 'PAR', 'b8eb36af-1274-4c81-add8-31afac0f1b84', 'd', 'Firearm Violence Prevention Act Part 4 s. 27 (3) (d)', NULL, 'the dates on which the shooting range is used or has been used by the shooting range user;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('abda28ca-51df-4950-aa56-c23bc1b0777c', 'PAR', 'b8eb36af-1274-4c81-add8-31afac0f1b84', 'e', 'Firearm Violence Prevention Act Part 4 s. 27 (3) (e)', NULL, 'prescribed information.', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('309d14f5-e06f-455b-a1a5-36eb2b014305', 'SUBSEC', 'd80f98bb-d2fc-4de2-83ad-48f4098850c4', '4', 'Firearm Violence Prevention Act Part 4 s. 27 (4)', NULL, 'Despite subsections (2) and (3), the shooting range records must contain the prescribed information about a shooting range user if the shooting range user', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fd453f0f-bc67-4adc-96f2-eddc1daae0be', 'PAR', '309d14f5-e06f-455b-a1a5-36eb2b014305', 'a', 'Firearm Violence Prevention Act Part 4 s. 27 (4) (a)', NULL, 'is a prescribed individual, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('871ebbb6-988f-4a53-9f35-87a8e2a57560', 'PAR', '309d14f5-e06f-455b-a1a5-36eb2b014305', 'b', 'Firearm Violence Prevention Act Part 4 s. 27 (4) (b)', NULL, 'uses the shooting range for a prescribed purpose.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6f51b9da-4751-4995-a71a-0e798bc1d746', 'SUBSEC', 'd80f98bb-d2fc-4de2-83ad-48f4098850c4', '5', 'Firearm Violence Prevention Act Part 4 s. 27 (5)', NULL, 'A shooting range user must provide to an operator of a shooting range the information required to be kept in shooting range records, as that information relates to the shooting range user.', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1bde671c-1f43-45c9-a9a4-a728b60cf2ca', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '28', 'Firearm Violence Prevention Act Part 4 s. 28', 'Premises where and period for which shooting range records must be kept', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('bd3b1475-8a3a-4a97-bf70-93da72cdfec3', 'SUBSEC', '1bde671c-1f43-45c9-a9a4-a728b60cf2ca', '1', 'Firearm Violence Prevention Act Part 4 s. 28 (1)', NULL, 'Shooting range records must be kept', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e7c7d8ff-f916-4ad5-acc3-e161e51a7fcb', 'PAR', 'bd3b1475-8a3a-4a97-bf70-93da72cdfec3', 'a', 'Firearm Violence Prevention Act Part 4 s. 28 (1) (a)', NULL, 'on the premises of the shooting range, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f67c3626-7aa4-4b4e-9b02-35eacc8171d0', 'PAR', 'bd3b1475-8a3a-4a97-bf70-93da72cdfec3', 'b', 'Firearm Violence Prevention Act Part 4 s. 28 (1) (b)', NULL, 'on other premises that the minister may specify.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d1034a8f-3403-4e73-82cc-e7450ecf505e', 'SUBSEC', '1bde671c-1f43-45c9-a9a4-a728b60cf2ca', '2', 'Firearm Violence Prevention Act Part 4 s. 28 (2)', NULL, 'Shooting range records must be kept in the form and manner, if any, that the minister specifies.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('db6603f0-4e0e-4cc0-9199-3053404a33b0', 'SUBSEC', '1bde671c-1f43-45c9-a9a4-a728b60cf2ca', '3', 'Firearm Violence Prevention Act Part 4 s. 28 (3)', NULL, 'Information contained in shooting range records must be kept for the prescribed period.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('080e9378-c3e6-4eaa-949f-1c67e40171e8', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '29', 'Firearm Violence Prevention Act Part 4 s. 29', 'Prohibition against providing false or misleading information in shooting range records', 'The following must not include or provide false or misleading information in relation to shooting range records:', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('55963d7b-55f9-4363-86e6-05dc2b09dcc1', 'PAR', '080e9378-c3e6-4eaa-949f-1c67e40171e8', 'a', 'Firearm Violence Prevention Act Part 4 s. 29 (a)', NULL, 'an operator of a shooting range;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ed0ec7a8-79d3-4535-ac14-72a26e9fa275', 'PAR', '080e9378-c3e6-4eaa-949f-1c67e40171e8', 'b', 'Firearm Violence Prevention Act Part 4 s. 29 (b)', NULL, 'a person who is on duty at a shooting range;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('77287dcf-bfe6-450a-9dc5-467afdb3e696', 'PAR', '080e9378-c3e6-4eaa-949f-1c67e40171e8', 'c', 'Firearm Violence Prevention Act Part 4 s. 29 (c)', NULL, 'a shooting range user.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c1039892-c963-4816-b1d2-aa9ab8f0b953', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '30', 'Firearm Violence Prevention Act Part 4 s. 30', 'Duty to require identification from shooting range user', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('30495969-e25f-4ae3-b59e-b6fc45e744c5', 'SUBSEC', 'c1039892-c963-4816-b1d2-aa9ab8f0b953', '1', 'Firearm Violence Prevention Act Part 4 s. 30 (1)', NULL, 'If an operator or another person is on duty at a shooting range, the person must, before a shooting range user uses a firearm or imitation firearm at the shooting range, require the shooting range user to produce the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('41b3588e-715d-4595-ba59-1da10bca8028', 'PAR', '30495969-e25f-4ae3-b59e-b6fc45e744c5', 'a', 'Firearm Violence Prevention Act Part 4 s. 30 (1) (a)', NULL, 'if the shooting range user is an adult, 2 pieces of prescribed identification;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('bdfec9ce-0903-496f-ab2e-a97314c00d9e', 'PAR', '30495969-e25f-4ae3-b59e-b6fc45e744c5', 'b', 'Firearm Violence Prevention Act Part 4 s. 30 (1) (b)', NULL, 'if the shooting range user is a minor, one piece of prescribed identification.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2bfdaa4f-6ada-4da3-9d95-10eef08b1b99', 'SUBSEC', 'c1039892-c963-4816-b1d2-aa9ab8f0b953', '2', 'Firearm Violence Prevention Act Part 4 s. 30 (2)', NULL, 'The regulations may establish exemptions in relation to a requirement under subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('83d3f544-0493-4943-b1fa-a2a6581d76b1', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '31', 'Firearm Violence Prevention Act Part 4 s. 31', 'Duty to require federal licence from shooting range user', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('32f2809e-c11e-4e14-9fee-08dbcde7f36a', 'SUBSEC', '83d3f544-0493-4943-b1fa-a2a6581d76b1', '1', 'Firearm Violence Prevention Act Part 4 s. 31 (1)', NULL, 'Subsection (2) applies in relation to a shooting range user who uses or proposes to use, at a shooting range, a firearm that is a non-restricted firearm, prohibited firearm or restricted firearm.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cd4f5f0f-65c2-4883-b9b1-633cb93e5644', 'SUBSEC', '83d3f544-0493-4943-b1fa-a2a6581d76b1', '2', 'Firearm Violence Prevention Act Part 4 s. 31 (2)', NULL, 'If an operator or another person is on duty at a shooting range and a shooting range user described in subsection (1)', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a38c6631-58ee-4fee-b88a-284bfee7f3d7', 'PAR', 'cd4f5f0f-65c2-4883-b9b1-633cb93e5644', 'a', 'Firearm Violence Prevention Act Part 4 s. 31 (2) (a)', NULL, 'indicates to the person on duty that the shooting range user is authorized to possess firearms under a federal licence, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a686724a-55b2-46b7-9d86-b0ff50820a6e', 'PAR', 'cd4f5f0f-65c2-4883-b9b1-633cb93e5644', 'b', 'Firearm Violence Prevention Act Part 4 s. 31 (2) (b)', NULL, 'provides to the person on duty the licence number of the federal licence of the shooting range user,', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0639420b-5860-4167-8527-927612dd2afa', 'TEXT', 'cd4f5f0f-65c2-4883-b9b1-633cb93e5644', NULL, 'Firearm Violence Prevention Act Part 4 s. 31 (2)', NULL, 'the person on duty must, for the purposes of verifying the information referred to in paragraphs (a) and (b) of this subsection, require the shooting range user to produce the federal licence.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('540aa31a-675d-42df-aac5-15614a48e82e', 'SUBSEC', '83d3f544-0493-4943-b1fa-a2a6581d76b1', '3', 'Firearm Violence Prevention Act Part 4 s. 31 (3)', NULL, 'The regulations may establish exemptions in relation to the requirement under subsection (2).', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('89960879-db32-492f-9451-648edfa63ed3', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '32', 'Firearm Violence Prevention Act Part 4 s. 32', 'Prohibition against using shooting range if identification or federal licence not produced', NULL, 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3fd1b503-cd92-4b6e-a8e4-75a04e7e04ae', 'SUBSEC', '89960879-db32-492f-9451-648edfa63ed3', '1', 'Firearm Violence Prevention Act Part 4 s. 32 (1)', NULL, 'A shooting range user must not use a firearm or imitation firearm at a shooting range if the shooting range user fails to do either of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('56cf0c18-3446-44b7-8777-48bb76384504', 'PAR', '3fd1b503-cd92-4b6e-a8e4-75a04e7e04ae', 'a', 'Firearm Violence Prevention Act Part 4 s. 32 (1) (a)', NULL, 'provide information as required under this Part in relation to shooting range records;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8608647c-2727-400b-aa0f-bde4a33a0ee9', 'PAR', '3fd1b503-cd92-4b6e-a8e4-75a04e7e04ae', 'b', 'Firearm Violence Prevention Act Part 4 s. 32 (1) (b)', NULL, 'produce identification as required under section 30 (1) [duty to require identification from shooting range user].', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('57641085-3616-4b05-803f-9cc7ab408a54', 'SUBSEC', '89960879-db32-492f-9451-648edfa63ed3', '2', 'Firearm Violence Prevention Act Part 4 s. 32 (2)', NULL, 'A shooting range user who fails to produce a federal licence to the person on duty at a shooting range, as required under section 31 (2), must not use a non-restricted firearm, prohibited firearm or restricted firearm at the shooting range.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7d20e34d-ea49-4664-912d-c3f22ab833a3', 'SEC', 'e65db662-5d87-40c6-86ac-e52e4f7ac92e', '33', 'Firearm Violence Prevention Act Part 4 s. 33', 'Power of person on duty to prohibit entry of shooting range user', 'An operator or another person who is on duty at a shooting range may prohibit a shooting range user from entering the shooting range, or may require a shooting range user to immediately leave the shooting range, if the shooting range user fails to do any of the following:', 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3eb7c332-f4c1-4c88-8c69-f787be7ad37a', 'PAR', '7d20e34d-ea49-4664-912d-c3f22ab833a3', 'a', 'Firearm Violence Prevention Act Part 4 s. 33 (a)', NULL, 'provide information as required under this Part in relation to shooting range records;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9cf7b042-7497-4d77-9adb-d49c0fee6c54', 'PAR', '7d20e34d-ea49-4664-912d-c3f22ab833a3', 'b', 'Firearm Violence Prevention Act Part 4 s. 33 (b)', NULL, 'produce identification as required under section 30 (1) [duty to require identification from shooting range user];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('24413304-87ca-4bd6-b180-b88a62d5a21c', 'PAR', '7d20e34d-ea49-4664-912d-c3f22ab833a3', 'c', 'Firearm Violence Prevention Act Part 4 s. 33 (c)', NULL, 'produce a federal licence as required under section 31 (2) [duty to require federal licence from shooting range user].', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('75160f91-14b9-40b8-ba06-56f7c4dbb86b', 'PART', 'da8abd55-5ee1-4c9d-9cb3-be977df3b081', '5', 'Firearm Violence Prevention Act Part 5', 'Motor Vehicle Impoundment', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b732ffcc-201d-4cb6-b8d7-19654de8ffc3', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '34', 'Firearm Violence Prevention Act Part 5 s. 34', 'Definitions for Part 5', 'In this Part:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('611cbb2f-abc4-465f-975e-bbf05c5db065', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'impound', '"impound", in relation to a motor vehicle, includes immobilizing the motor vehicle at a location specified by a peace officer who is authorized under either of the following to cause the motor vehicle to be impounded:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2e7d4c2a-2c6b-46e3-9b43-0be1a69c2af6', 'PAR', '611cbb2f-abc4-465f-975e-bbf05c5db065', 'a', 'Firearm Violence Prevention Act Part 5 s. 34 (a)', NULL, 'section 35;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f5175067-ed47-4bed-a588-2735419d1820', 'PAR', '611cbb2f-abc4-465f-975e-bbf05c5db065', 'b', 'Firearm Violence Prevention Act Part 5 s. 34 (b)', NULL, 'an impoundment order;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0437182b-0165-4673-8edc-29a6a5fd837a', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'impoundment lien', '"impoundment lien" means a lien under section 42 (1) [impoundment costs constitute lien];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('43f80c00-f7c3-438c-a9ab-02c2cf8ae326', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'impoundment order', '"impoundment order" means an order of a justice under section 36 (1) [order of justice to impound motor vehicle];', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('564dd1c1-9baa-4dd8-a80f-e5cf9c70f035', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'impoundment period', '"impoundment period" means the period prescribed for the purposes of sections 35 (2) and 36 (2) (b);', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b6fed944-8dd5-48a1-b4f8-fc7f96e52697', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'motor vehicle', '"motor vehicle" has the same meaning as in section 1 [definitions] of the Motor Vehicle Act;', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('83c0c415-aa61-470f-84f9-eb4cf488bb16', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'owner', '"owner" has the same meaning as in section 1 of the Motor Vehicle Act;', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('75eea999-3f46-4119-bf3e-80b8260428fc', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'peace officer', '"peace officer" means either of the following:', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('28cfe16b-af66-42b4-8a77-8f8607aa0f2a', 'PAR', '75eea999-3f46-4119-bf3e-80b8260428fc', 'a', 'Firearm Violence Prevention Act Part 5 s. 34 (a)', NULL, 'a peace officer as described in paragraph (c) of the definition of "peace officer" in section 29 [expressions defined] of the Interpretation Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('dda8dea5-51ba-4b31-896f-8ff5008c08af', 'PAR', '75eea999-3f46-4119-bf3e-80b8260428fc', 'b', 'Firearm Violence Prevention Act Part 5 s. 34 (b)', NULL, 'a prescribed person;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('50c0b286-0aeb-4f9a-9bdc-6c505abfda87', 'DEF', 'b732ffcc-201d-4cb6-b8d7-19654de8ffc3', NULL, 'Firearm Violence Prevention Act Part 5 s. 34', 'person who has custody', '"person who has custody", in relation to a motor vehicle, includes a person who has impounded a motor vehicle by immobilizing the motor vehicle.', 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('bf130658-31cc-4b56-80a9-c721305d7196', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '35', 'Firearm Violence Prevention Act Part 5 s. 35', 'Power of peace officer to impound motor vehicle', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a55d9f5d-f716-4f8c-9276-0f055692f2b3', 'SUBSEC', 'bf130658-31cc-4b56-80a9-c721305d7196', '1', 'Firearm Violence Prevention Act Part 5 s. 35 (1)', NULL, 'A peace officer may cause a motor vehicle to be impounded and taken to a specified location if the peace officer reasonably believes that a person is operating or has operated the motor vehicle in contravention of', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('78a48eea-5a1d-4e88-a10e-351e82a83359', 'PAR', 'a55d9f5d-f716-4f8c-9276-0f055692f2b3', 'a', 'Firearm Violence Prevention Act Part 5 s. 35 (1) (a)', NULL, 'section 6 (2) [prohibition against operating vehicle if certain firearms, ammunition or devices in vehicle], or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e1db5961-0a16-4521-a23b-e22c306ce139', 'PAR', 'a55d9f5d-f716-4f8c-9276-0f055692f2b3', 'b', 'Firearm Violence Prevention Act Part 5 s. 35 (1) (b)', NULL, 'section 320.17 of the Criminal Code.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b77c8a88-7950-400e-87d4-f21f9952fb2b', 'SUBSEC', 'bf130658-31cc-4b56-80a9-c721305d7196', '2', 'Firearm Violence Prevention Act Part 5 s. 35 (2)', NULL, 'A motor vehicle impounded under subsection (1) must remain impounded for the prescribed period.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e32bdbb7-baae-452b-8626-9d579a3906f4', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '36', 'Firearm Violence Prevention Act Part 5 s. 36', 'Order of justice to impound motor vehicle', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0655c3e6-4b7f-452a-9ab5-d6f9b22ed23d', 'SUBSEC', 'e32bdbb7-baae-452b-8626-9d579a3906f4', '1', 'Firearm Violence Prevention Act Part 5 s. 36 (1)', NULL, 'On application by a peace officer, a justice may by order authorize a peace officer to cause a motor vehicle to be impounded if the justice is satisfied that there are reasonable grounds to believe that the motor vehicle has been operated in contravention of', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3c3e7385-6acb-4472-9fe5-9b702dde69c5', 'PAR', '0655c3e6-4b7f-452a-9ab5-d6f9b22ed23d', 'a', 'Firearm Violence Prevention Act Part 5 s. 36 (1) (a)', NULL, 'section 6 (2) [prohibition against operating vehicle if certain firearms, ammunition or devices in vehicle], or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('69e6af4b-bfbc-488b-9cc3-59772b87904e', 'PAR', '0655c3e6-4b7f-452a-9ab5-d6f9b22ed23d', 'b', 'Firearm Violence Prevention Act Part 5 s. 36 (1) (b)', NULL, 'section 320.17 of the Criminal Code.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('dfda9cff-9b33-42f8-b4ce-1a18e42a4262', 'SUBSEC', 'e32bdbb7-baae-452b-8626-9d579a3906f4', '2', 'Firearm Violence Prevention Act Part 5 s. 36 (2)', NULL, 'An impoundment order must contain the following information:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('49cf2023-83fa-4b6a-833b-bcd628dddcb3', 'PAR', 'dfda9cff-9b33-42f8-b4ce-1a18e42a4262', 'a', 'Firearm Violence Prevention Act Part 5 s. 36 (2) (a)', NULL, 'that, unless the owner or a person authorized by the owner discharges the impoundment lien, the impounded motor vehicle may be disposed of in accordance with this Part or the Warehouse Lien Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('add05b1d-adf3-4ade-ba3f-b5bb8ba4e3b2', 'PAR', 'dfda9cff-9b33-42f8-b4ce-1a18e42a4262', 'b', 'Firearm Violence Prevention Act Part 5 s. 36 (2) (b)', NULL, 'that, unless the motor vehicle is released in accordance with this Part before the end of the prescribed period, the motor vehicle must remain impounded for the prescribed period.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f82c00e7-64ad-4428-9ac6-48b279e38202', 'SUBSEC', 'e32bdbb7-baae-452b-8626-9d579a3906f4', '3', 'Firearm Violence Prevention Act Part 5 s. 36 (3)', NULL, 'Unless an impoundment order specifies otherwise, a motor vehicle authorized to be impounded under the order is to be impounded at a location specified by the peace officer who enforces that order.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('61691bb2-2651-4469-a0a8-13a4831697f6', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '37', 'Firearm Violence Prevention Act Part 5 s. 37', 'Duty of peace officer to be present when motor vehicle impounded', 'If a peace officer causes a motor vehicle to be impounded and taken from its present location to a specified location, a peace officer must be present when the motor vehicle is being removed from the present location.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b95f86d4-c16d-4419-b5ae-411d76cc2e76', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '38', 'Firearm Violence Prevention Act Part 5 s. 38', 'Duty of peace officer to arrange transportation for occupants', 'A peace officer who causes a motor vehicle to be impounded must arrange for the occupants of the motor vehicle to be transported to the nearest safe area where the occupants can obtain an alternative form of transportation if the peace officer considers that the impoundment would', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('14fbc445-30c3-49c0-802b-f83b29a5f0f2', 'PAR', 'b95f86d4-c16d-4419-b5ae-411d76cc2e76', 'a', 'Firearm Violence Prevention Act Part 5 s. 38 (a)', NULL, 'jeopardize the safety of the occupants, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('668c4302-b4b9-4b2f-b0b7-59cbb49e7d6c', 'PAR', 'b95f86d4-c16d-4419-b5ae-411d76cc2e76', 'b', 'Firearm Violence Prevention Act Part 5 s. 38 (b)', NULL, 'leave the occupants stranded.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b147ae02-0c16-44e7-b968-78c25e5e6e47', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '39', 'Firearm Violence Prevention Act Part 5 s. 39', 'Notice of impoundment', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fd3a05e7-6f41-46af-a1fc-4909963cfda3', 'SUBSEC', 'b147ae02-0c16-44e7-b968-78c25e5e6e47', '1', 'Firearm Violence Prevention Act Part 5 s. 39 (1)', NULL, 'A peace officer who causes a motor vehicle to be impounded must give written notice of the impoundment to each of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c027d660-14ba-4873-aea6-fa74d071cd8e', 'PAR', 'fd3a05e7-6f41-46af-a1fc-4909963cfda3', 'a', 'Firearm Violence Prevention Act Part 5 s. 39 (1) (a)', NULL, 'the minister;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a41e088a-4c05-4dac-b4d3-2fb567e894fa', 'PAR', 'fd3a05e7-6f41-46af-a1fc-4909963cfda3', 'b', 'Firearm Violence Prevention Act Part 5 s. 39 (1) (b)', NULL, 'if a person was operating or in possession of the motor vehicle at the time of its impoundment, the person who was operating or in possession of the motor vehicle;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f1e4dcfe-85f9-41f4-99a7-9eb5e04d1f3a', 'PAR', 'fd3a05e7-6f41-46af-a1fc-4909963cfda3', 'c', 'Firearm Violence Prevention Act Part 5 s. 39 (1) (c)', NULL, 'the person who has custody of the motor vehicle;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('55486368-d613-4c94-86ac-8f3f2db1f089', 'PAR', 'fd3a05e7-6f41-46af-a1fc-4909963cfda3', 'd', 'Firearm Violence Prevention Act Part 5 s. 39 (1) (d)', NULL, 'a prescribed person, if any.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8fa00228-5857-44c2-9a85-e1a8d56e8903', 'SUBSEC', 'b147ae02-0c16-44e7-b968-78c25e5e6e47', '2', 'Firearm Violence Prevention Act Part 5 s. 39 (2)', NULL, 'The notice under subsection (1) must contain the information described in section 36 (2) (a) and (b) [order of justice to impound motor vehicle].', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('aeeae589-dd1d-4e67-abda-22dffea041f0', 'SUBSEC', 'b147ae02-0c16-44e7-b968-78c25e5e6e47', '3', 'Firearm Violence Prevention Act Part 5 s. 39 (3)', NULL, 'Promptly after receiving a notice of impoundment under subsection (1) (a), the minister must send a copy of the notice to the last known address of the registered owner of the motor vehicle, as shown in the records maintained by the Insurance Corporation of British Columbia, unless the registered owner is a person to whom the peace officer has already given notice under subsection (1) (b).', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('17cfd414-86fc-4c30-94d7-9f8427a3d6c7', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '40', 'Firearm Violence Prevention Act Part 5 s. 40', 'Duty of operator to notify owner of impoundment', 'If the person who was operating or in possession of a motor vehicle at the time of its impoundment is not the owner of the motor vehicle, the person must take reasonable steps to promptly notify the owner of the impoundment.', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('34837374-a233-4332-a15d-327809396cf1', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '41', 'Firearm Violence Prevention Act Part 5 s. 41', 'Duty of person who has custody to return personal property', 'On request of the owner of an impounded motor vehicle, the person who has custody of the motor vehicle must return to the owner any personal property in the motor vehicle, other than personal property attached to or used in connection with the operation of the motor vehicle.', 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b5a966c1-5ae7-4f38-b9fb-4ea7cf8c3766', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '42', 'Firearm Violence Prevention Act Part 5 s. 42', 'Impoundment costs constitute lien', NULL, 9, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6587ee5a-c56f-49fb-9453-aac4633ac3de', 'SUBSEC', 'b5a966c1-5ae7-4f38-b9fb-4ea7cf8c3766', '1', 'Firearm Violence Prevention Act Part 5 s. 42 (1)', NULL, 'The fees, costs, charges, surcharges and amounts described in section 255 (2) [lien on impounded motor vehicle] of the Motor Vehicle Act constitute a lien on an impounded motor vehicle, as if the motor vehicle were impounded under section 251 (1) [impoundment of motor vehicle] of that Act.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e30aca94-ed1f-44d7-917d-e26f87f2f2e3', 'SUBSEC', 'b5a966c1-5ae7-4f38-b9fb-4ea7cf8c3766', '2', 'Firearm Violence Prevention Act Part 5 s. 42 (2)', NULL, 'An impoundment lien may be enforced under section 46 [power of person who has custody to dispose of motor vehicle] or, if the impoundment lien is not discharged under this Part, under the Warehouse Lien Act.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('910be997-02b3-462c-8bed-404e0771f229', 'SUBSEC', 'b5a966c1-5ae7-4f38-b9fb-4ea7cf8c3766', '3', 'Firearm Violence Prevention Act Part 5 s. 42 (3)', NULL, 'The person who has custody of an impounded motor vehicle must promptly notify the minister if the motor vehicle is sold under the Warehouse Lien Act.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5a5b46ea-5d35-4759-b25b-fe297875f0ea', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '43', 'Firearm Violence Prevention Act Part 5 s. 43', 'Period for which motor vehicle must remain impounded', 'Except as otherwise provided in this Part, an impounded motor vehicle must remain impounded during the impoundment period and for a further period that ends as follows:', 10, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('677b3d75-6076-4628-b089-343198ab2f90', 'PAR', '5a5b46ea-5d35-4759-b25b-fe297875f0ea', 'a', 'Firearm Violence Prevention Act Part 5 s. 43 (a)', NULL, 'if the impoundment lien on the motor vehicle is discharged after the end of the impoundment period, when the impoundment lien is discharged and the requirements for release under section 44 are met;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('55b5ed5d-b1b2-4ccc-90ac-71377af41a63', 'PAR', '5a5b46ea-5d35-4759-b25b-fe297875f0ea', 'b', 'Firearm Violence Prevention Act Part 5 s. 43 (b)', NULL, 'if an agreement is made under section 45 [agreement to take no action before specified date], when the date specified in the agreement is reached and the requirements for release under section 44 are met;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('86e30c4d-dc3b-4a55-bb57-320b6705bb16', 'PAR', '5a5b46ea-5d35-4759-b25b-fe297875f0ea', 'c', 'Firearm Violence Prevention Act Part 5 s. 43 (c)', NULL, 'if the motor vehicle is disposed of under section 46 [power of person who has custody to dispose of motor vehicle] or the Warehouse Lien Act, when the motor vehicle is disposed of.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b774ec3b-7995-4182-9b71-0a232989e1ab', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '44', 'Firearm Violence Prevention Act Part 5 s. 44', 'Request and order for release after impoundment period ends', 'Unless the regulations provide otherwise, the person who has custody of an impounded motor vehicle must release the motor vehicle to the owner or a person authorized by the owner if each of the following requirements has been met:', 11, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6dd36ae6-1d70-4654-beca-cbfdd97a73e8', 'PAR', 'b774ec3b-7995-4182-9b71-0a232989e1ab', 'a', 'Firearm Violence Prevention Act Part 5 s. 44 (a)', NULL, 'the owner or a person authorized by the owner has delivered to the minister a request for the release of the motor vehicle;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('834bbb19-a7e7-4311-880a-0f4ef6898a77', 'PAR', 'b774ec3b-7995-4182-9b71-0a232989e1ab', 'b', 'Firearm Violence Prevention Act Part 5 s. 44 (b)', NULL, 'the minister, after receiving a request referred to in paragraph (a), has issued an order requiring that the motor vehicle be released to the owner or a person authorized by the owner, subject to the requirements in paragraphs (c) and (d) being met;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('851f07ed-b129-4307-aa74-e0a88317b58b', 'PAR', 'b774ec3b-7995-4182-9b71-0a232989e1ab', 'c', 'Firearm Violence Prevention Act Part 5 s. 44 (c)', NULL, 'the owner or a person authorized by the owner has discharged the impoundment lien;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6a389421-b630-4101-ac2f-1c47efad7253', 'PAR', 'b774ec3b-7995-4182-9b71-0a232989e1ab', 'd', 'Firearm Violence Prevention Act Part 5 s. 44 (d)', NULL, 'the impoundment period has ended or, if an agreement referred to in section 45 is in place, the date for release under that agreement has been reached.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3e9e9ec7-af2d-4834-8faa-b493b3cf040d', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '45', 'Firearm Violence Prevention Act Part 5 s. 45', 'Agreement to take no action before specified date', NULL, 12, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8e549994-f237-482f-b0cb-a2c8054c02f5', 'SUBSEC', '3e9e9ec7-af2d-4834-8faa-b493b3cf040d', '1', 'Firearm Violence Prevention Act Part 5 s. 45 (1)', NULL, 'The person who has custody of an impounded motor vehicle may enter into an agreement with the owner of the motor vehicle respecting the earliest date, after the impoundment period ends, that the person will begin to take action to dispose of the motor vehicle.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('72a8a476-8db5-4345-9c05-81c9854b9be1', 'SUBSEC', '3e9e9ec7-af2d-4834-8faa-b493b3cf040d', '2', 'Firearm Violence Prevention Act Part 5 s. 45 (2)', NULL, 'The person who has custody of an impounded motor vehicle must promptly notify the minister of an agreement entered into under subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e6f47fd3-d712-451a-8403-74b4066be61b', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '46', 'Firearm Violence Prevention Act Part 5 s. 46', 'Power of person who has custody to dispose of motor vehicle', 'The person who has custody of an impounded motor vehicle may dispose of the motor vehicle if the following requirements are met:', 13, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('dd29a34b-f17a-4560-bdb8-d92b0c79e4d7', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'a', 'Firearm Violence Prevention Act Part 5 s. 46 (a)', NULL, 'the motor vehicle remains impounded after the end of the impoundment period;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4826aff4-bfad-4f12-8eee-28f3c5f6b32a', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'b', 'Firearm Violence Prevention Act Part 5 s. 46 (b)', NULL, 'the amount of the impoundment lien on the motor vehicle exceeds the value of the motor vehicle, as estimated by the person who has custody, less $1 000;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3a7720c6-d37b-4e81-9cf6-6e9db13c3788', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'c', 'Firearm Violence Prevention Act Part 5 s. 46 (c)', NULL, 'by notice sent by mail at least 14 days before the filing of the statutory declaration under paragraph (e) of this section, the registered owner of the motor vehicle has been informed that the person who has custody intends to dispose of the motor vehicle if the impoundment lien is not discharged;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3fc383fe-8737-4615-983f-65e6283ca071', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'd', 'Firearm Violence Prevention Act Part 5 s. 46 (d)', NULL, 'the person who has custody has obtained a certificate issued under the Personal Property Security Act showing that no security interest is registered against the motor vehicle;', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('83eef95a-0fc5-4287-b5d8-5446aa82c5d3', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'e', 'Firearm Violence Prevention Act Part 5 s. 46 (e)', NULL, 'the person who has custody has filed a statutory declaration with the minister declaring that the requirements set out in paragraphs (b), (c) and (d) of this section have been met;', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('56f81b15-b1f7-4c1a-915b-e9ce047bbab7', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'f', 'Firearm Violence Prevention Act Part 5 s. 46 (f)', NULL, 'the person who has custody has surrendered to the Insurance Corporation of British Columbia any number plates, issued under the Motor Vehicle Act, from the motor vehicle;', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('616e1e7e-f0c9-4fa6-8c26-3855669a8803', 'PAR', 'e6f47fd3-d712-451a-8403-74b4066be61b', 'g', 'Firearm Violence Prevention Act Part 5 s. 46 (g)', NULL, 'the person who has custody has obtained the minister''s approval respecting the disposal of the motor vehicle.', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('10c5862a-bb72-402f-96b8-28f532c041c7', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '47', 'Firearm Violence Prevention Act Part 5 s. 47', 'Minister''s duties if disposal of motor vehicle approved', 'If the person who has custody obtains the minister''s approval under section 46 (g), the minister must direct the Insurance Corporation of British Columbia to do the following:', 14, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('31e46985-4de5-4386-a7e4-6e1524c7c579', 'PAR', '10c5862a-bb72-402f-96b8-28f532c041c7', 'a', 'Firearm Violence Prevention Act Part 5 s. 47 (a)', NULL, 'cancel any vehicle licence issued under the Motor Vehicle Act with respect to the motor vehicle;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1d7e7030-6c1d-4103-9cdb-4008e2310830', 'PAR', '10c5862a-bb72-402f-96b8-28f532c041c7', 'b', 'Firearm Violence Prevention Act Part 5 s. 47 (b)', NULL, 'transfer the registration of the motor vehicle to the person who has custody of the impounded motor vehicle;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4fd75d85-fb0b-4b29-a6d8-27da94aebcfd', 'PAR', '10c5862a-bb72-402f-96b8-28f532c041c7', 'c', 'Firearm Violence Prevention Act Part 5 s. 47 (c)', NULL, 'forward any refund from the cancellation of the vehicle licence to the previous registered owner of the motor vehicle.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('76125e58-bdfb-4829-8690-b5efdb022c6e', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '48', 'Firearm Violence Prevention Act Part 5 s. 48', 'Power of minister to direct refusal of licence if impoundment lien not discharged', NULL, 15, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9c319667-3e77-4310-af62-81ac585a19b0', 'SUBSEC', '76125e58-bdfb-4829-8690-b5efdb022c6e', '1', 'Firearm Violence Prevention Act Part 5 s. 48 (1)', NULL, 'If the person who has custody obtains the minister''s approval under section 46 (g) [power of person who has custody to dispose of motor vehicle], the minister, not less than 30 days after giving that approval, may direct that, until the direction is rescinded under subsection (2) of this section, the Insurance Corporation of British Columbia is to do one or both of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('86a6f2c4-40c7-4c72-a91c-02572a772ac7', 'PAR', '9c319667-3e77-4310-af62-81ac585a19b0', 'a', 'Firearm Violence Prevention Act Part 5 s. 48 (1) (a)', NULL, 'refuse to issue a driver''s licence, under section 26 (1) [refusal to issue a licence, permit, etc.] of the Motor Vehicle Act, to the person who was the owner of the motor vehicle at the time of its impoundment;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('609f8f46-34bb-41b9-bad3-dc1dfdf038f6', 'PAR', '9c319667-3e77-4310-af62-81ac585a19b0', 'b', 'Firearm Violence Prevention Act Part 5 s. 48 (1) (b)', NULL, 'refuse to issue, under section 26 (2) of the Motor Vehicle Act, to the person who was the owner of the motor vehicle at the time of its impoundment, a licence and corresponding number plates for a motor vehicle or trailer, or both.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a93a9787-8591-4e3c-9558-d264275f5048', 'SUBSEC', '76125e58-bdfb-4829-8690-b5efdb022c6e', '2', 'Firearm Violence Prevention Act Part 5 s. 48 (2)', NULL, 'If the amount of an impoundment lien on a motor vehicle is discharged by disposal of the motor vehicle under section 46 or by payment by the person who was the owner of the motor vehicle at the time of its impoundment, or by a combination of both,', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5d138795-4670-4bad-8ab6-fac89f0a1279', 'PAR', 'a93a9787-8591-4e3c-9558-d264275f5048', 'a', 'Firearm Violence Prevention Act Part 5 s. 48 (2) (a)', NULL, 'the person who filed a statutory declaration under section 46 (e) or who received the payment must promptly notify the minister of the discharge, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a8fd691c-6d1c-4207-a707-7696620e11e8', 'PAR', 'a93a9787-8591-4e3c-9558-d264275f5048', 'b', 'Firearm Violence Prevention Act Part 5 s. 48 (2) (b)', NULL, 'after being notified under paragraph (a) of this subsection, the minister must rescind the direction, if any, given to the Insurance Corporation of British Columbia under subsection (1) of this section.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b4682b10-a308-4b93-840b-1032951cf66e', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '49', 'Firearm Violence Prevention Act Part 5 s. 49', 'Power to make agreement to transfer motor vehicle for parts or scrap', NULL, 16, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c7a2699a-a501-42b2-98f2-dcb54f5e5476', 'SUBSEC', 'b4682b10-a308-4b93-840b-1032951cf66e', '1', 'Firearm Violence Prevention Act Part 5 s. 49 (1)', NULL, 'The owner of an impounded motor vehicle and the person who has custody of the motor vehicle may enter into an agreement under which', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('57c72e13-e5e2-4d34-a976-7fc38230646f', 'PAR', 'c7a2699a-a501-42b2-98f2-dcb54f5e5476', 'a', 'Firearm Violence Prevention Act Part 5 s. 49 (1) (a)', NULL, 'the owner agrees to transfer title to the motor vehicle to the person who has custody of the motor vehicle, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7154712a-ba3e-4715-af6d-c54752558139', 'PAR', 'c7a2699a-a501-42b2-98f2-dcb54f5e5476', 'b', 'Firearm Violence Prevention Act Part 5 s. 49 (1) (b)', NULL, 'the person who has custody of the motor vehicle agrees to transfer title to the motor vehicle to a person who', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ec5b29c6-d198-453a-a1fe-7fabf2274bdd', 'SUBPAR', '7154712a-ba3e-4715-af6d-c54752558139', 'i', 'Firearm Violence Prevention Act Part 5 s. 49 (1) (b) (i)', NULL, 'is in the business of wrecking used motor vehicles, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cc0fb478-fdd8-4fbd-b314-136e6ba44616', 'SUBPAR', '7154712a-ba3e-4715-af6d-c54752558139', 'ii', 'Firearm Violence Prevention Act Part 5 s. 49 (1) (b) (ii)', NULL, 'intends to use the motor vehicle for parts or scrap.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('13a90a1b-cb5e-4b16-8695-8326644e58cb', 'SUBSEC', 'b4682b10-a308-4b93-840b-1032951cf66e', '2', 'Firearm Violence Prevention Act Part 5 s. 49 (2)', NULL, 'If the owner and the person who has custody enter into an agreement under subsection (1),', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('56d6fb64-8835-4e2e-8021-4a4d081bf873', 'PAR', '13a90a1b-cb5e-4b16-8695-8326644e58cb', 'a', 'Firearm Violence Prevention Act Part 5 s. 49 (2) (a)', NULL, 'on the owner and the person entering into the agreement, the impoundment lien on the motor vehicle is discharged, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('990f287d-069e-4435-b8d9-86fcc8672d6a', 'PAR', '13a90a1b-cb5e-4b16-8695-8326644e58cb', 'b', 'Firearm Violence Prevention Act Part 5 s. 49 (2) (b)', NULL, 'whether or not the impoundment period has ended, the person who has custody of the motor vehicle must dispose of the motor vehicle to a person described in subsection (1) (b) (i) and (ii).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4964477e-54ad-4472-92fd-74fe79c41dea', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '50', 'Firearm Violence Prevention Act Part 5 s. 50', 'Duties of person who has custody after receiving transfer of title', NULL, 17, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ca44d528-a6de-40fc-b170-6c16bf878df4', 'SUBSEC', '4964477e-54ad-4472-92fd-74fe79c41dea', '1', 'Firearm Violence Prevention Act Part 5 s. 50 (1)', NULL, 'Within 10 days after title to a motor vehicle has been transferred, in accordance with an agreement entered into under section 49 (1), to the person who has custody of the motor vehicle, the person must deliver to the Insurance Corporation of British Columbia a notice of transfer and change in status of the motor vehicle, together with payment of the required fee.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3df6956c-5f56-4d59-a409-6c18936446c7', 'SUBSEC', '4964477e-54ad-4472-92fd-74fe79c41dea', '2', 'Firearm Violence Prevention Act Part 5 s. 50 (2)', NULL, 'For the purposes of subsection (1),', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3e350819-624d-40b5-8f73-228fe42fece7', 'PAR', '3df6956c-5f56-4d59-a409-6c18936446c7', 'a', 'Firearm Violence Prevention Act Part 5 s. 50 (2) (a)', NULL, 'the notice of transfer and change in status must be', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f0240f1f-4239-419b-b90c-be0cfe274482', 'SUBPAR', '3e350819-624d-40b5-8f73-228fe42fece7', 'i', 'Firearm Violence Prevention Act Part 5 s. 50 (2) (a) (i)', NULL, 'in the same form as required by the Insurance Corporation of British Columbia for the purposes of section 255 (9) (c) [notice of transfer and change of status of motor vehicle transferred as irreparable vehicle] of the Motor Vehicle Act, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1bdb05e3-bcc5-46b9-98c8-bcaf409955c1', 'SUBPAR', '3e350819-624d-40b5-8f73-228fe42fece7', 'ii', 'Firearm Violence Prevention Act Part 5 s. 50 (2) (a) (ii)', NULL, 'signed by the owner and the person who has custody of the motor vehicle, and', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('84f2f770-38c5-4dfe-bcdb-380031b06faf', 'PAR', '3df6956c-5f56-4d59-a409-6c18936446c7', 'b', 'Firearm Violence Prevention Act Part 5 s. 50 (2) (b)', NULL, 'the required fee must be paid in the same amount as prescribed by the Superintendent of Motor Vehicles for the purposes of section 17.1 (3) (b) [fee for transfer of motor vehicle as irreparable or salvage vehicle] of the Motor Vehicle Act.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ceed0612-774c-4021-b0ce-2d3dee4ea4db', 'SUBSEC', '4964477e-54ad-4472-92fd-74fe79c41dea', '3', 'Firearm Violence Prevention Act Part 5 s. 50 (3)', NULL, 'Section 255 (10) [storage of impounded vehicle] of the Motor Vehicle Act applies in respect of the delivery of a notice of transfer and change in status under subsection (1) of this section.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8b9c4e93-722b-4d8c-919e-6ed45b05b9f3', 'SUBSEC', '4964477e-54ad-4472-92fd-74fe79c41dea', '4', 'Firearm Violence Prevention Act Part 5 s. 50 (4)', NULL, 'Before transferring the motor vehicle to a person described in section 49 (1) (b) (i) and (ii), the person who has custody of the motor vehicle must do all of the following:', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c2dca372-6855-49ca-b016-9731d9a8e9a1', 'PAR', '8b9c4e93-722b-4d8c-919e-6ed45b05b9f3', 'a', 'Firearm Violence Prevention Act Part 5 s. 50 (4) (a)', NULL, 'surrender to the Insurance Corporation of British Columbia any number plates, issued under the Motor Vehicle Act, from the motor vehicle;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5f7faf4a-277f-41a4-b77a-38eddd2486a9', 'PAR', '8b9c4e93-722b-4d8c-919e-6ed45b05b9f3', 'b', 'Firearm Violence Prevention Act Part 5 s. 50 (4) (b)', NULL, 'file a request for approval with the minister that includes the following:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cfefa58f-7022-4921-a8ff-a33a6ce87353', 'SUBPAR', '5f7faf4a-277f-41a4-b77a-38eddd2486a9', 'i', 'Firearm Violence Prevention Act Part 5 s. 50 (4) (b) (i)', NULL, 'a copy of the agreement entered into under section 49 (1);', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2c99aaa2-ba86-4bea-8f06-4071a5569244', 'SUBPAR', '5f7faf4a-277f-41a4-b77a-38eddd2486a9', 'ii', 'Firearm Violence Prevention Act Part 5 s. 50 (4) (b) (ii)', NULL, 'a statutory declaration that the person has obtained a certificate issued under the Personal Property Security Act showing that no security interest is registered against the motor vehicle;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f42b6731-0202-4392-bbbe-64f3b4d676ed', 'PAR', '8b9c4e93-722b-4d8c-919e-6ed45b05b9f3', 'c', 'Firearm Violence Prevention Act Part 5 s. 50 (4) (c)', NULL, 'obtain the approval of the minister.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('12702f96-3f77-4b5f-a884-4950277c6d97', 'SUBSEC', '4964477e-54ad-4472-92fd-74fe79c41dea', '5', 'Firearm Violence Prevention Act Part 5 s. 50 (5)', NULL, 'If the person who has custody obtains the minister''s approval under subsection (4) (c), the minister must perform the duties described in section 47 [minister''s duties if disposal of motor vehicle approved].', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d25e225d-250d-463a-a30a-3a3c2883e909', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '51', 'Firearm Violence Prevention Act Part 5 s. 51', 'Duty of peace officer to order early release if motor vehicle stolen property', NULL, 18, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2893dffe-a576-4153-8fde-b82539596f44', 'SUBSEC', 'd25e225d-250d-463a-a30a-3a3c2883e909', '1', 'Firearm Violence Prevention Act Part 5 s. 51 (1)', NULL, 'If a peace officer is satisfied that a motor vehicle impounded under section 35 [power of peace officer to impound motor vehicle] is stolen property, the peace officer must order the person who has custody of the motor vehicle to promptly release the motor vehicle, after the impoundment lien has been discharged, to the owner or a person authorized by the owner.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f8d68b9b-c5d6-4468-8bfa-ddb48fc1b071', 'SUBSEC', 'd25e225d-250d-463a-a30a-3a3c2883e909', '2', 'Firearm Violence Prevention Act Part 5 s. 51 (2)', NULL, 'A peace officer must promptly notify the minister of an order given under subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('13a6e88e-3a0c-4dc2-90dc-53833bea51cb', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '52', 'Firearm Violence Prevention Act Part 5 s. 52', 'Duty of peace officer to order early release if contravention did not occur', NULL, 19, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('58b6597f-6042-4b60-95ee-6615e9262ba7', 'SUBSEC', '13a6e88e-3a0c-4dc2-90dc-53833bea51cb', '1', 'Firearm Violence Prevention Act Part 5 s. 52 (1)', NULL, 'A peace officer who causes a motor vehicle to be impounded under section 35 [power of peace officer to impound motor vehicle] must order the person who has custody of the motor vehicle to release the motor vehicle, after the impoundment lien has been discharged, to the owner or a person authorized by the owner if both of the following apply:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7ac6f6f5-f9b1-44dc-8b3a-53bb46ba87a3', 'PAR', '58b6597f-6042-4b60-95ee-6615e9262ba7', 'a', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (a)', NULL, 'when the motor vehicle was impounded, the peace officer reasonably believed that the motor vehicle was being or had been operated in contravention of', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('32509d37-2f4f-4f9b-bb30-7cc001935a27', 'SUBPAR', '7ac6f6f5-f9b1-44dc-8b3a-53bb46ba87a3', 'i', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (a) (i)', NULL, 'section 6 (2) [prohibition against operating vehicle if certain firearms, ammunition or devices in vehicle], or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3451c199-d685-4f28-8c8d-8f2fc6c49570', 'SUBPAR', '7ac6f6f5-f9b1-44dc-8b3a-53bb46ba87a3', 'ii', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (a) (ii)', NULL, 'section 320.17 of the Criminal Code;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cbe360ab-116c-4ad8-a59e-095639bf2d68', 'PAR', '58b6597f-6042-4b60-95ee-6615e9262ba7', 'b', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (b)', NULL, 'based on information or records provided to the peace officer after the motor vehicle was impounded, the peace officer is satisfied that at the time of its impoundment the motor vehicle was not being or had not been operated in contravention of', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('121a572b-73f5-4a39-a79a-657d02f516f2', 'SUBPAR', 'cbe360ab-116c-4ad8-a59e-095639bf2d68', 'i', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (b) (i)', NULL, 'section 6 (2) of this Act, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('369fb685-948d-4f35-8f8f-2662ec97f8e1', 'SUBPAR', 'cbe360ab-116c-4ad8-a59e-095639bf2d68', 'ii', 'Firearm Violence Prevention Act Part 5 s. 52 (1) (b) (ii)', NULL, 'section 320.17 of the Criminal Code.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4306e936-a825-4a47-b931-dcfcfd249b8d', 'SUBSEC', '13a6e88e-3a0c-4dc2-90dc-53833bea51cb', '2', 'Firearm Violence Prevention Act Part 5 s. 52 (2)', NULL, 'A peace officer must promptly notify the minister of an order given under subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('776a19ea-a89a-439e-81c2-c1fd2877eb08', 'SUBSEC', '13a6e88e-3a0c-4dc2-90dc-53833bea51cb', '3', 'Firearm Violence Prevention Act Part 5 s. 52 (3)', NULL, 'The regulations may specify information or records that may or must be provided to a peace officer for the purposes of subsection (1) (b).', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4286c8fa-c766-4ef4-82d6-bcc35b69e8ad', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '53', 'Firearm Violence Prevention Act Part 5 s. 53', 'Power of owner to recover impoundment costs from driver', NULL, 20, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0371cd86-fe83-4e4f-94eb-92066d23cfd0', 'SUBSEC', '4286c8fa-c766-4ef4-82d6-bcc35b69e8ad', '1', 'Firearm Violence Prevention Act Part 5 s. 53 (1)', NULL, 'If the owner of an impounded motor vehicle has discharged all or a portion of the impoundment lien, the owner may recover the amount paid from the person reasonably believed to have been operating the motor vehicle in contravention of', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2d04fa03-a351-4348-a89c-3cb8155e9e8e', 'PAR', '0371cd86-fe83-4e4f-94eb-92066d23cfd0', 'a', 'Firearm Violence Prevention Act Part 5 s. 53 (1) (a)', NULL, 'section 6 (2) of this Act, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cfa4f223-166b-42d3-96d4-b83e00339198', 'PAR', '0371cd86-fe83-4e4f-94eb-92066d23cfd0', 'b', 'Firearm Violence Prevention Act Part 5 s. 53 (1) (b)', NULL, 'section 320.17 of the Criminal Code.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('811596a7-7549-4a56-af26-72edf2bbcdea', 'SUBSEC', '4286c8fa-c766-4ef4-82d6-bcc35b69e8ad', '2', 'Firearm Violence Prevention Act Part 5 s. 53 (2)', NULL, 'An amount referred to in subsection (1) is recoverable, as a debt due, in a court that has jurisdiction.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7450b684-5c5c-48ec-8d08-3a323c5d5c07', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '54', 'Firearm Violence Prevention Act Part 5 s. 54', 'Access to information in records of Insurance Corporation of British Columbia', NULL, 21, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('99ad1540-a51c-4b87-85f1-3707b2501bb8', 'SUBSEC', '7450b684-5c5c-48ec-8d08-3a323c5d5c07', '1', 'Firearm Violence Prevention Act Part 5 s. 54 (1)', NULL, 'The Insurance Corporation of British Columbia must give to the minister, on request, information contained in records kept by the corporation relating to an impounded motor vehicle.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('245ef110-1a95-464d-9e47-5afe252143ee', 'SUBSEC', '7450b684-5c5c-48ec-8d08-3a323c5d5c07', '2', 'Firearm Violence Prevention Act Part 5 s. 54 (2)', NULL, 'The minister may use and disclose information given under subsection (1) for the purposes of exercising the minister''s powers or performing the minister''s duties under this Part.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1dee0790-4d0a-4453-a854-e585d1cd6581', 'SEC', '75160f91-14b9-40b8-ba06-56f7c4dbb86b', '55', 'Firearm Violence Prevention Act Part 5 s. 55', 'Power of minister to specify form and manner of records', 'The minister may specify any of the following in respect of a notification, request, agreement, declaration or other record required or permitted under this Part:', 22, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fb2e5b47-3589-47dd-befe-9560ebad487b', 'PAR', '1dee0790-4d0a-4453-a854-e585d1cd6581', 'a', 'Firearm Violence Prevention Act Part 5 s. 55 (a)', NULL, 'the form and manner in which the record must be completed, filed, given or delivered;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4f406906-20ca-45dc-8bfc-1e78c79c2e7c', 'PAR', '1dee0790-4d0a-4453-a854-e585d1cd6581', 'b', 'Firearm Violence Prevention Act Part 5 s. 55 (b)', NULL, 'information or additional information that must be included in the record.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1911a21b-42e1-4736-8711-d3233cbff195', 'PART', 'da8abd55-5ee1-4c9d-9cb3-be977df3b081', '6', 'Firearm Violence Prevention Act Part 6', 'Inspection, Search, Seizure and Arrest', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ab17164d-6278-4b42-a865-38d23a4f9c51', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '56', 'Firearm Violence Prevention Act Part 6 s. 56', 'Definition for Part 6', 'In this Part, "peace officer" means either of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('435fb6ab-08a2-40df-bf9c-d6576497f9cc', 'PAR', 'ab17164d-6278-4b42-a865-38d23a4f9c51', 'a', 'Firearm Violence Prevention Act Part 6 s. 56 (a)', NULL, 'a peace officer as described in paragraph (c) of the definition of "peace officer" in section 29 [expressions defined] of the Interpretation Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('df96fd04-a096-4d60-8cd7-026f22a1ac38', 'PAR', 'ab17164d-6278-4b42-a865-38d23a4f9c51', 'b', 'Firearm Violence Prevention Act Part 6 s. 56 (b)', NULL, 'a prescribed person.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('29e82867-755f-412f-a17e-7876ee2c10b1', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '57', 'Firearm Violence Prevention Act Part 6 s. 57', 'Duty to permit peace officer to inspect certain weapons and things', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8c8ff66a-0934-4812-b6de-edcff156f29c', 'SUBSEC', '29e82867-755f-412f-a17e-7876ee2c10b1', '1', 'Firearm Violence Prevention Act Part 6 s. 57 (1)', NULL, 'On request of a peace officer who is exercising a power or performing a duty of the peace officer, a person must immediately produce and permit inspection of a weapon or thing that is or appears to be a firearm, imitation firearm, prohibited device or ammunition.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('998db33c-50f5-41b7-bf5c-338b59fa593d', 'SUBSEC', '29e82867-755f-412f-a17e-7876ee2c10b1', '2', 'Firearm Violence Prevention Act Part 6 s. 57 (2)', NULL, 'Without limiting subsection (1), a peace officer may inspect a weapon or thing described in that subsection that is seen or found in or on a vehicle or boat.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a3cbfd91-2d19-48b4-92b5-c56f06b474f9', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '58', 'Firearm Violence Prevention Act Part 6 s. 58', 'Search and seizure with warrant', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('72e5788e-c03a-44d4-8e7d-dd9932e4b186', 'SUBSEC', 'a3cbfd91-2d19-48b4-92b5-c56f06b474f9', '1', 'Firearm Violence Prevention Act Part 6 s. 58 (1)', NULL, 'On information on oath or affirmation that there are reasonable grounds to believe an offence under this Act has occurred or is occurring, a justice, on being satisfied that an entry and search are likely to provide evidence of an offence under this Act, may issue a warrant authorizing a peace officer to do any of the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ca1f36df-9914-4c58-98a6-f386dd704591', 'PAR', '72e5788e-c03a-44d4-8e7d-dd9932e4b186', 'a', 'Firearm Violence Prevention Act Part 6 s. 58 (1) (a)', NULL, 'enter and search the real or personal property specified in the warrant;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c3a50eca-e85f-409e-addb-e00be1dab424', 'PAR', '72e5788e-c03a-44d4-8e7d-dd9932e4b186', 'b', 'Firearm Violence Prevention Act Part 6 s. 58 (1) (b)', NULL, 'search a person who the peace officer reasonably believes has possession of anything that is likely to provide evidence of an offence under this Act;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('dc9329fc-8691-4bba-b44c-7aa233d4977c', 'PAR', '72e5788e-c03a-44d4-8e7d-dd9932e4b186', 'c', 'Firearm Violence Prevention Act Part 6 s. 58 (1) (c)', NULL, 'seize and remove anything that the peace officer reasonably believes is evidence of an offence under this Act;', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cb387414-5dbb-4f63-aef1-2cd7c743048e', 'PAR', '72e5788e-c03a-44d4-8e7d-dd9932e4b186', 'd', 'Firearm Violence Prevention Act Part 6 s. 58 (1) (d)', NULL, 'take other actions the justice authorizes in the warrant.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('74c52529-dee8-4829-9684-b0a37822229b', 'SUBSEC', 'a3cbfd91-2d19-48b4-92b5-c56f06b474f9', '2', 'Firearm Violence Prevention Act Part 6 s. 58 (2)', NULL, 'The regulations may prescribe the form of an information or warrant for the purposes of subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9721f058-324f-4dbe-ac7d-08a869d08666', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '59', 'Firearm Violence Prevention Act Part 6 s. 59', 'Search and seizure without warrant', NULL, 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('09b04d42-5a6c-4b46-b450-dd8ad4ae47f6', 'SUBSEC', '9721f058-324f-4dbe-ac7d-08a869d08666', '1', 'Firearm Violence Prevention Act Part 6 s. 59 (1)', NULL, 'A peace officer may exercise a power referred to in section 58 (1) (a), (b) or (c), without a warrant, if the peace officer reasonably believes the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2c403d49-a0e2-422c-b7b2-c16bad288510', 'PAR', '09b04d42-5a6c-4b46-b450-dd8ad4ae47f6', 'a', 'Firearm Violence Prevention Act Part 6 s. 59 (1) (a)', NULL, 'an offence under this Act has occurred or is occurring;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e0218d39-8916-4832-a90b-1a8f4cf3b8f6', 'PAR', '09b04d42-5a6c-4b46-b450-dd8ad4ae47f6', 'b', 'Firearm Violence Prevention Act Part 6 s. 59 (1) (b)', NULL, 'an entry and search are likely to provide evidence of an offence under this Act;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7006c137-9d77-4cfa-8f25-c81845a751e9', 'PAR', '09b04d42-5a6c-4b46-b450-dd8ad4ae47f6', 'c', 'Firearm Violence Prevention Act Part 6 s. 59 (1) (c)', NULL, 'the delay necessary to obtain a warrant would result in', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('07e431b9-ebec-46d1-9c43-2ffe7c09d8f4', 'SUBPAR', '7006c137-9d77-4cfa-8f25-c81845a751e9', 'i', 'Firearm Violence Prevention Act Part 6 s. 59 (1) (c) (i)', NULL, 'the loss or destruction of evidence, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0f6e198a-eca2-491e-be4a-6cf26a628b43', 'SUBPAR', '7006c137-9d77-4cfa-8f25-c81845a751e9', 'ii', 'Firearm Violence Prevention Act Part 6 s. 59 (1) (c) (ii)', NULL, 'a danger to human life or safety.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e9ad9ead-dec4-48ee-85e8-5b52e9542ee9', 'SUBSEC', '9721f058-324f-4dbe-ac7d-08a869d08666', '2', 'Firearm Violence Prevention Act Part 6 s. 59 (2)', NULL, 'Unless a peace officer reasonably believes that the delay necessary to obtain a warrant would result in a danger to human life or safety, the peace officer may not, under subsection (1), enter and search', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('599deded-6b2c-4e8b-8ab5-6b110db28d8f', 'PAR', 'e9ad9ead-dec4-48ee-85e8-5b52e9542ee9', 'a', 'Firearm Violence Prevention Act Part 6 s. 59 (2) (a)', NULL, 'a premises occupied solely as a private residence, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a5c55294-825a-4cac-9cf0-3937e3df2046', 'PAR', 'e9ad9ead-dec4-48ee-85e8-5b52e9542ee9', 'b', 'Firearm Violence Prevention Act Part 6 s. 59 (2) (b)', NULL, 'if only part of a premises is occupied solely as a private residence, that part of the premises.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4cb6d1b7-85c5-4af7-87f8-b91ea3cca745', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '60', 'Firearm Violence Prevention Act Part 6 s. 60', 'Application of Offence Act to warrant, search and seizure', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d1ba23ff-6c72-4356-b55b-abc85b9b5385', 'SUBSEC', '4cb6d1b7-85c5-4af7-87f8-b91ea3cca745', '1', 'Firearm Violence Prevention Act Part 6 s. 60 (1)', NULL, 'The following provisions of the Offence Act apply in relation to a warrant under section 58 [search and seizure with warrant] of this Act and to a search and anything seized under the warrant or section 59 of this Act:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3d4097b4-9507-4880-9e4b-36a5eb83a9c8', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'a', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (a)', NULL, 'section 21 (4) [search warrants];', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f3d54004-27f5-40f4-b30a-5ba11b307f0d', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'b', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (b)', NULL, 'section 22 [telewarrants];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('477b1235-f4cd-4dc4-911a-07cb2b7b0daa', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'c', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (c)', NULL, 'section 23 [seizure of things not specified];', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('063cb5ed-02b9-4bf2-848f-6567afe208f2', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'd', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (d)', NULL, 'section 24 [detention of things seized];', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('61535b35-20ac-4214-b6b5-6c9b78359470', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'e', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (e)', NULL, 'section 24.1 [access to thing seized];', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3924b2b8-f92c-4099-abe8-ea3dd27b2cce', 'PAR', 'd1ba23ff-6c72-4356-b55b-abc85b9b5385', 'f', 'Firearm Violence Prevention Act Part 6 s. 60 (1) (f)', NULL, 'subject to section 61 of this Act, section 24.2 [order for disposition of thing seized].', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7099281c-8da3-4da7-86f7-8510a532b694', 'SUBSEC', '4cb6d1b7-85c5-4af7-87f8-b91ea3cca745', '2', 'Firearm Violence Prevention Act Part 6 s. 60 (2)', NULL, 'Despite section 24 (3) of the Offence Act, if, under section 24 (2) (a) of that Act, a justice orders that a thing must be detained, the thing may be detained for up to one year before an order under section 24 (5) of that Act, authorizing its continued detention, is required.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('10c18d2d-e997-4c61-8721-9833bb62a169', 'SEC', '1911a21b-42e1-4736-8711-d3233cbff195', '61', 'Firearm Violence Prevention Act Part 6 s. 61', 'Certain seized weapons and things forfeit to government', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4b670269-32f1-4bba-9983-3831c8d4a84d', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '1', 'Firearm Violence Prevention Act Part 6 s. 61 (1)', NULL, 'In this section, "seized weapon or thing" means a firearm, imitation firearm, prohibited device, cartridge magazine or ammunition that is seized and detained under this Part.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f2fa474e-736c-4d6c-9e95-3460e242223e', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '2', 'Firearm Violence Prevention Act Part 6 s. 61 (2)', NULL, 'Unless a justice orders otherwise under subsection (4), a seized weapon or thing is forfeited to the government if a justice determines any of the following:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f67a54e3-bbe3-4832-a6e7-91157dda6238', 'PAR', 'f2fa474e-736c-4d6c-9e95-3460e242223e', 'a', 'Firearm Violence Prevention Act Part 6 s. 61 (2) (a)', NULL, 'the seized weapon or thing was used in the commission of an offence under this Act;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d4f96c89-0d52-4e47-a729-b3925a75abac', 'PAR', 'f2fa474e-736c-4d6c-9e95-3460e242223e', 'b', 'Firearm Violence Prevention Act Part 6 s. 61 (2) (b)', NULL, 'a person has committed an offence under this Act that involves the seized weapon or thing.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0650bf83-2ff3-4838-bcef-fb42a030bf64', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '3', 'Firearm Violence Prevention Act Part 6 s. 61 (3)', NULL, 'Unless a justice orders otherwise under subsection (4), a seized weapon or thing is forfeited to the government if all of the following requirements are met:', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2b6a6ac7-a38c-4126-8cae-779ec06553ca', 'PAR', '0650bf83-2ff3-4838-bcef-fb42a030bf64', 'a', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (a)', NULL, 'a person is alleged to have contravened a provision of this Act or the regulations;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('54b5ac04-9cb4-42be-a93f-9beaad610345', 'PAR', '0650bf83-2ff3-4838-bcef-fb42a030bf64', 'b', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (b)', NULL, 'the alleged contravention involves the seized weapon or thing;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('96b8368b-3f92-40af-9a5e-0431e6e7db43', 'PAR', '0650bf83-2ff3-4838-bcef-fb42a030bf64', 'c', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (c)', NULL, 'the person is deemed, under any of the following provisions of the Offence Act, to have pleaded guilty to the alleged contravention:', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c4ba50e4-c678-4ec1-8a02-bc8e5ad8d90f', 'SUBPAR', '96b8368b-3f92-40af-9a5e-0431e6e7db43', 'i', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (c) (i)', NULL, 'section 14 (11) [person deemed guilty on payment of all or portion of violation ticket];', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1f6c7894-8c71-49f4-8728-c7d47a711565', 'SUBPAR', '96b8368b-3f92-40af-9a5e-0431e6e7db43', 'ii', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (c) (ii)', NULL, 'section 15 (12) [person deemed guilty on failure to appear];', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('3f1fad4b-e89d-476d-82fa-40196def4a3f', 'SUBPAR', '96b8368b-3f92-40af-9a5e-0431e6e7db43', 'iii', 'Firearm Violence Prevention Act Part 6 s. 61 (3) (c) (iii)', NULL, 'section 16 (1) [person deemed guilty on failure to respond to violation ticket].', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('78e499bd-852e-4799-99b8-64f22c52293e', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '4', 'Firearm Violence Prevention Act Part 6 s. 61 (4)', NULL, 'A justice may order that a seized weapon or thing that is or may be forfeited under subsection (2) or (3) be returned to a person if the justice is satisfied that', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2f8bbe2e-1410-4640-a472-72a7092b53a5', 'PAR', '78e499bd-852e-4799-99b8-64f22c52293e', 'a', 'Firearm Violence Prevention Act Part 6 s. 61 (4) (a)', NULL, 'the person is the lawful owner of the seized weapon or thing,', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a76b1674-8ce4-4eb4-9f9a-5ec27dfe29d9', 'PAR', '78e499bd-852e-4799-99b8-64f22c52293e', 'b', 'Firearm Violence Prevention Act Part 6 s. 61 (4) (b)', NULL, 'the person was not a party to the offence or contravention to which the determination relates, and', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('40537bf8-8a41-48d8-837e-00a91ddab65b', 'PAR', '78e499bd-852e-4799-99b8-64f22c52293e', 'c', 'Firearm Violence Prevention Act Part 6 s. 61 (4) (c)', NULL, 'the person had no reasonable grounds to believe that the seized weapon or thing would or might be used in the commission of the offence or contravention to which the determination relates.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6c08b29d-11f7-4bc8-abe8-af00ca1039ff', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '5', 'Firearm Violence Prevention Act Part 6 s. 61 (5)', NULL, 'If a seized weapon or thing has been destroyed, the justice may order that an amount equal to the value of the seized weapon or thing be paid to a person who meets the requirements set out in subsection (4).', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4ce032e9-c740-48c2-a9de-795cdff47687', 'SUBSEC', '10c18d2d-e997-4c61-8721-9833bb62a169', '6', 'Firearm Violence Prevention Act Part 6 s. 61 (6)', NULL, 'A seized weapon or thing that is forfeited to the government may be disposed of as the minister may direct.', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
