  ('82661650-6efe-41de-ba3e-ff930f10d69e', 'SUBSEC', 'd0746877-6e0f-49da-811d-4b3398a0bef4', '2', 'Firearm Violence Prevention Act Part 7 s. 66 (2)', NULL, 'Unless subsection (3) applies, a person who commits an offence under subsection (1) is liable,', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ad2e188c-9415-4ecb-86e3-b5834f5fc2e8', 'PAR', '82661650-6efe-41de-ba3e-ff930f10d69e', 'a', 'Firearm Violence Prevention Act Part 7 s. 66 (2) (a)', NULL, 'if the person is an individual, to a fine of not more than $2 500, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b1b6cf08-d96d-49ab-bd69-9fde95a8cc0f', 'PAR', '82661650-6efe-41de-ba3e-ff930f10d69e', 'b', 'Firearm Violence Prevention Act Part 7 s. 66 (2) (b)', NULL, 'if the person is not an individual, to a fine of not more than $50 000.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c66ec1b3-328c-4095-87e9-150ec7f10363', 'SUBSEC', 'd0746877-6e0f-49da-811d-4b3398a0bef4', '3', 'Firearm Violence Prevention Act Part 7 s. 66 (3)', NULL, 'If a person who commits an offence under subsection (1) has, within the previous 5 years, committed the same offence or another offence under this Act, the person is liable,', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a926dde8-fdfd-470b-9f6b-06466e31a08c', 'PAR', 'c66ec1b3-328c-4095-87e9-150ec7f10363', 'a', 'Firearm Violence Prevention Act Part 7 s. 66 (3) (a)', NULL, 'if the person is an individual, to a fine of not more than $5 000, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('31f5d9dc-ccd3-4a00-b0e6-7b643e54e1b2', 'PAR', 'c66ec1b3-328c-4095-87e9-150ec7f10363', 'b', 'Firearm Violence Prevention Act Part 7 s. 66 (3) (b)', NULL, 'if the person is not an individual, to a fine of not more than $100 000.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('118ed49d-2e4a-463b-b703-9aa233c023a9', 'SUBSEC', 'd0746877-6e0f-49da-811d-4b3398a0bef4', '4', 'Firearm Violence Prevention Act Part 7 s. 66 (4)', NULL, 'A person who contravenes section 49 (2) (b) [requirements under agreement to transfer motor vehicle for parts or scrap] commits an offence.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5abd4dbc-9197-4a3d-bc26-d0c295709b8d', 'SUBSEC', 'd0746877-6e0f-49da-811d-4b3398a0bef4', '5', 'Firearm Violence Prevention Act Part 7 s. 66 (5)', NULL, 'A person who commits an offence under subsection (4) is liable to one or both of the following:', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0cff32bb-6504-4c38-86f6-2e9a3e9dec81', 'PAR', '5abd4dbc-9197-4a3d-bc26-d0c295709b8d', 'a', 'Firearm Violence Prevention Act Part 7 s. 66 (5) (a)', NULL, 'a fine of not more than $2 000;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('efed6924-a9bc-4bd8-9442-26f01779c4f1', 'PAR', '5abd4dbc-9197-4a3d-bc26-d0c295709b8d', 'b', 'Firearm Violence Prevention Act Part 7 s. 66 (5) (b)', NULL, 'imprisonment for not more than 6 months.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8c1a6549-35ad-40b6-8532-569aa9270525', 'SEC', '8dd76044-1b82-4c65-8892-e8d57c79e122', '67', 'Firearm Violence Prevention Act Part 7 s. 67', 'Certificate evidence', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9a60adce-eb9f-4ea8-891b-15ab64ea92fb', 'SUBSEC', '8c1a6549-35ad-40b6-8532-569aa9270525', '1', 'Firearm Violence Prevention Act Part 7 s. 67 (1)', NULL, 'In this section, "certificate" means a certificate that', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('490bf706-9ad5-4227-b976-7e9dffead28a', 'PAR', '9a60adce-eb9f-4ea8-891b-15ab64ea92fb', 'a', 'Firearm Violence Prevention Act Part 7 s. 67 (1) (a)', NULL, 'is signed by a person who is employed or authorized by a laboratory operated, maintained, supported or certified by', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('413eda3f-16b3-4e69-834b-4d76ff783daf', 'SUBPAR', '490bf706-9ad5-4227-b976-7e9dffead28a', 'i', 'Firearm Violence Prevention Act Part 7 s. 67 (1) (a) (i)', NULL, 'the government, the government of another province or the government of Canada, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5a943b0c-fc8d-4265-9814-87b86ee5fa08', 'SUBPAR', '490bf706-9ad5-4227-b976-7e9dffead28a', 'ii', 'Firearm Violence Prevention Act Part 7 s. 67 (1) (a) (ii)', NULL, 'a prescribed person or entity, and', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fed405c1-578d-4130-a5d3-b12618af8b16', 'PAR', '9a60adce-eb9f-4ea8-891b-15ab64ea92fb', 'b', 'Firearm Violence Prevention Act Part 7 s. 67 (1) (b)', NULL, 'contains factual information relating to the person''s analysis of a firearm, imitation firearm, prohibited device or ammunition.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('aef6b037-85ad-4dd6-b339-76d72a1bbaba', 'SUBSEC', '8c1a6549-35ad-40b6-8532-569aa9270525', '2', 'Firearm Violence Prevention Act Part 7 s. 67 (2)', NULL, 'In a proceeding relating to the contravention of a provision of this Act or the regulations, a certificate is', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e8a04f88-9eb7-45b6-9cc2-bed9dee955c6', 'PAR', 'aef6b037-85ad-4dd6-b339-76d72a1bbaba', 'a', 'Firearm Violence Prevention Act Part 7 s. 67 (2) (a)', NULL, 'admissible in evidence,', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a6f91b75-b8a6-4a42-8f90-4100f4846698', 'PAR', 'aef6b037-85ad-4dd6-b339-76d72a1bbaba', 'b', 'Firearm Violence Prevention Act Part 7 s. 67 (2) (b)', NULL, 'evidence of the facts stated in the certificate, and', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('16fdcc7a-b134-451f-b88a-4c591bd44840', 'PAR', 'aef6b037-85ad-4dd6-b339-76d72a1bbaba', 'c', 'Firearm Violence Prevention Act Part 7 s. 67 (2) (c)', NULL, 'conclusive evidence of the authority of the person signing the certificate, without further proof of the person''s signature, employment or authorization.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('23bacc56-f2bf-4c9e-9e53-7779b2141ac8', 'SEC', '8dd76044-1b82-4c65-8892-e8d57c79e122', '68', 'Firearm Violence Prevention Act Part 7 s. 68', 'Court order to prohibit possession', NULL, 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d94e32de-66c7-472f-876c-dad6ab8e0df4', 'SUBSEC', '23bacc56-f2bf-4c9e-9e53-7779b2141ac8', '1', 'Firearm Violence Prevention Act Part 7 s. 68 (1)', NULL, 'If a person is convicted of or pleads guilty or is deemed to have pleaded guilty to a prescribed offence under this Act, a court may by order, on application or on the court''s own initiative, prohibit the person from possessing a firearm, imitation firearm, prohibited device or prohibited ammunition for the period specified in the order.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('31dc22c6-ad71-4530-abdd-10749625422b', 'SUBSEC', '23bacc56-f2bf-4c9e-9e53-7779b2141ac8', '2', 'Firearm Violence Prevention Act Part 7 s. 68 (2)', NULL, 'An order under subsection (1) is in addition to any other punishment that may be imposed.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0ffd87d5-2b14-4dde-a24a-4a347c56f51c', 'SEC', '8dd76044-1b82-4c65-8892-e8d57c79e122', '69', 'Firearm Violence Prevention Act Part 7 s. 69', 'Offences involving corporations', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c05e60e8-05f8-47dd-ade6-834dcfa7f1b1', 'SUBSEC', '0ffd87d5-2b14-4dde-a24a-4a347c56f51c', '1', 'Firearm Violence Prevention Act Part 7 s. 69 (1)', NULL, 'If a corporation or limited liability company commits an offence under this Act, an officer, director or agent of the corporation or limited liability company who authorizes, allows or participates in the offence also commits an offence, whether or not the corporation or limited liability company is prosecuted or convicted.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('098b4534-6735-4a7e-b120-4ff6b84a6e5d', 'SUBSEC', '0ffd87d5-2b14-4dde-a24a-4a347c56f51c', '2', 'Firearm Violence Prevention Act Part 7 s. 69 (2)', NULL, 'In a prosecution for an offence under this Act, it is sufficient proof of the offence to establish that the offence was committed by an officer, director or agent of a corporation or limited liability company, whether or not the officer, director or agent is prosecuted or convicted.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('cd7c56a8-99e1-4153-819c-050728abe77f', 'SUBSEC', '0ffd87d5-2b14-4dde-a24a-4a347c56f51c', '3', 'Firearm Violence Prevention Act Part 7 s. 69 (3)', NULL, 'For the purposes of subsection (2), a corporation or limited liability company has the burden of proving that an officer, director or agent of the corporation or limited liability company was not acting on behalf of the corporation or limited liability company at the time the officer, director or agent committed an offence under this Act.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('de12237b-e932-4120-b6d6-7ba1f0c6f0b2', 'SEC', '8dd76044-1b82-4c65-8892-e8d57c79e122', '70', 'Firearm Violence Prevention Act Part 7 s. 70', 'Time limit for prosecuting offence', 'The time limit for laying an information for an offence under this Act is 6 years after the date on which the act or omission that is alleged to constitute the offence occurred.', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('36bdacfb-f6d9-478e-818d-ab631d277feb', 'SEC', '8dd76044-1b82-4c65-8892-e8d57c79e122', '71', 'Firearm Violence Prevention Act Part 7 s. 71', 'Section 5 of Offence Act does not apply', 'Section 5 [general offence] of the Offence Act does not apply to this Act or the regulations.', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2b930ed0-cb05-4e93-9d93-fd4637f08a8c', 'PART', 'da8abd55-5ee1-4c9d-9cb3-be977df3b081', '8', 'Firearm Violence Prevention Act Part 8', 'General', NULL, 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ae7d78af-418f-4894-8f4a-fe110e8b0af4', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '72', 'Firearm Violence Prevention Act Part 8 s. 72', 'Power of authorized professional to notify police despite confidentiality', NULL, 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('964c5d80-783e-44da-a43f-1b17e808c9d6', 'SUBSEC', 'ae7d78af-418f-4894-8f4a-fe110e8b0af4', '1', 'Firearm Violence Prevention Act Part 8 s. 72 (1)', NULL, 'In this section:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('36b2b051-20d0-4d66-9ccd-9f9d5c5d4f22', 'DEF', '964c5d80-783e-44da-a43f-1b17e808c9d6', NULL, 'Firearm Violence Prevention Act Part 8 s. 72 (1)', 'authorized professional', '"authorized professional" means a designated health professional, social worker or any other individual, other than a lawyer, who', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f5e05317-9891-4ac7-a5c4-95d337228eed', 'PAR', '36b2b051-20d0-4d66-9ccd-9f9d5c5d4f22', 'a', 'Firearm Violence Prevention Act Part 8 s. 72 (1) (a)', NULL, 'provides professional services, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6bd88eba-8909-42ab-9365-d786e3cb9305', 'PAR', '36b2b051-20d0-4d66-9ccd-9f9d5c5d4f22', 'b', 'Firearm Violence Prevention Act Part 8 s. 72 (1) (b)', NULL, 'owes a duty of confidentiality to persons to whom those professional services are provided;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e8328d32-ebb6-48ee-a0e3-8a2267135ade', 'DEF', '964c5d80-783e-44da-a43f-1b17e808c9d6', NULL, 'Firearm Violence Prevention Act Part 8 s. 72 (1)', 'designated health professional', '"designated health professional" means an individual who is authorized to practise a designated health profession within the meaning of section 1 [definitions] of the Health Professions Act;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('437b2430-cdda-48f0-b2a9-155e27ed11c5', 'DEF', '964c5d80-783e-44da-a43f-1b17e808c9d6', NULL, 'Firearm Violence Prevention Act Part 8 s. 72 (1)', 'police force', '"police force" means a police force within the meaning of section 1.1 (a), (b) or (c) [police forces in British Columbia] of the Police Act.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f9499f8e-d79a-4a9a-9802-28e20efdd978', 'SUBSEC', 'ae7d78af-418f-4894-8f4a-fe110e8b0af4', '2', 'Firearm Violence Prevention Act Part 8 s. 72 (2)', NULL, 'Despite any duty of confidentiality, an authorized professional may notify a police force if the authorized professional reasonably believes that a person to whom that authorized professional provides professional services intends to use a firearm or imitation firearm', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7e8b89b6-416b-4ceb-acc3-fd06f11e0a0e', 'PAR', 'f9499f8e-d79a-4a9a-9802-28e20efdd978', 'a', 'Firearm Violence Prevention Act Part 8 s. 72 (2) (a)', NULL, 'to cause harm to themselves or another person, or', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9118247f-960f-4bee-9888-0dfa8defcdaf', 'PAR', 'f9499f8e-d79a-4a9a-9802-28e20efdd978', 'b', 'Firearm Violence Prevention Act Part 8 s. 72 (2) (b)', NULL, 'to threaten or intimidate another person.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('be5ac1d6-a431-4d32-b7a4-3ffb17fb707a', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '73', 'Firearm Violence Prevention Act Part 8 s. 73', 'Liability protection in respect of authorized professionals', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('99a36fae-9c7a-4cae-93ef-f5434e317753', 'SUBSEC', 'be5ac1d6-a431-4d32-b7a4-3ffb17fb707a', '1', 'Firearm Violence Prevention Act Part 8 s. 73 (1)', NULL, 'Subject to subsection (2), no legal proceeding for damages lies or may be commenced or maintained against any of the following because of anything done or omitted under section 72 (2):', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('93095cac-fe85-4147-8d69-ba54961f7c96', 'PAR', '99a36fae-9c7a-4cae-93ef-f5434e317753', 'a', 'Firearm Violence Prevention Act Part 8 s. 73 (1) (a)', NULL, 'an authorized professional;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('244a1447-e517-4426-93eb-9f88430ea5b9', 'PAR', '99a36fae-9c7a-4cae-93ef-f5434e317753', 'b', 'Firearm Violence Prevention Act Part 8 s. 73 (1) (b)', NULL, 'an employer, other than the government, of an authorized professional.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d4029054-2d71-4135-a226-7144b970dd48', 'SUBSEC', 'be5ac1d6-a431-4d32-b7a4-3ffb17fb707a', '2', 'Firearm Violence Prevention Act Part 8 s. 73 (2)', NULL, 'Subsection (1) does not apply to an authorized professional or employer in relation to anything done or omitted in bad faith.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0982a611-1aad-4a2a-b430-0446286a6953', 'SUBSEC', 'be5ac1d6-a431-4d32-b7a4-3ffb17fb707a', '3', 'Firearm Violence Prevention Act Part 8 s. 73 (3)', NULL, 'Subsection (1) (a) does not absolve the government from vicarious liability arising out of anything done or omitted by an authorized professional for which the government would be liable if this section were not in force.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('17e10d3f-2ad4-4641-9ed1-d329a32b3423', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '74', 'Firearm Violence Prevention Act Part 8 s. 74', 'Duty to provide information about low-velocity firearms', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('f5f07a61-4c8e-47c2-8383-7b928722666f', 'SUBSEC', '17e10d3f-2ad4-4641-9ed1-d329a32b3423', '1', 'Firearm Violence Prevention Act Part 8 s. 74 (1)', NULL, 'A person who carries on the business of selling, renting or supplying low-velocity firearms must give a person to whom a low-velocity firearm is sold, rented or supplied information that', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c1e4bb23-ea54-4bbf-a6fd-dd812a1ec00d', 'PAR', 'f5f07a61-4c8e-47c2-8383-7b928722666f', 'a', 'Firearm Violence Prevention Act Part 8 s. 74 (1) (a)', NULL, 'is provided in the form and manner, if any, that the minister may specify, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('29c2a204-25e5-4d84-8a0b-e135824898b4', 'PAR', 'f5f07a61-4c8e-47c2-8383-7b928722666f', 'b', 'Firearm Violence Prevention Act Part 8 s. 74 (1) (b)', NULL, 'includes the content that the minister specifies.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('26987cf0-a86f-4ef6-8c90-1b5e731aeba0', 'SUBSEC', '17e10d3f-2ad4-4641-9ed1-d329a32b3423', '2', 'Firearm Violence Prevention Act Part 8 s. 74 (2)', NULL, 'The regulations may establish exemptions in relation to a requirement under subsection (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('21f89e21-e95d-426e-86d5-11811ee9296b', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '75', 'Firearm Violence Prevention Act Part 8 s. 75', 'Prohibition against providing false or misleading information about low-velocity firearms', 'A person required under section 74 (1) to give information about low-velocity firearms must not provide false or misleading information about the low-velocity firearms to persons to whom those low-velocity firearms are sold, rented or supplied.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('da43f102-7c04-47bc-8c68-432657e869cb', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '76', 'Firearm Violence Prevention Act Part 8 s. 76', 'Prohibition against producing false or misleading identification', 'A person must not, for any purpose under this Act, produce identification that', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ed6bc541-d384-4e99-bbcd-ce08a7e5755b', 'PAR', 'da43f102-7c04-47bc-8c68-432657e869cb', 'a', 'Firearm Violence Prevention Act Part 8 s. 76 (a)', NULL, 'has been altered to misrepresent the person''s age or identity,', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('451c1876-31fa-4304-983e-b9d9cdf3318a', 'PAR', 'da43f102-7c04-47bc-8c68-432657e869cb', 'b', 'Firearm Violence Prevention Act Part 8 s. 76 (b)', NULL, 'was issued by the issuing agency to another person, or', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('66fb82cb-f4d0-4176-a86c-fffe5fcd9478', 'PAR', 'da43f102-7c04-47bc-8c68-432657e869cb', 'c', 'Firearm Violence Prevention Act Part 8 s. 76 (c)', NULL, 'was forged or fraudulently made.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('27268c17-2ec3-4f44-8397-73d568636c5e', 'SEC', '2b930ed0-cb05-4e93-9d93-fd4637f08a8c', '77', 'Firearm Violence Prevention Act Part 8 s. 77', 'Prohibition against producing false or misleading federal licence or authorization', 'A person must not, for any purpose under this Act, produce a federal licence or an authorization given under the federal Act that', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
