  ('36c4368e-17bb-4550-a362-28c24984296e', 'PAR', '56c7f834-9609-4bec-974b-bf79f283096c', 'a', 'Firearm Violence Prevention Act Part 9 s. 82 (3) (a)', NULL, 'specify purposes for which or circumstances in which an exemption applies;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ad123c54-0392-48e8-b1be-0c9094cf5115', 'PAR', '56c7f834-9609-4bec-974b-bf79f283096c', 'b', 'Firearm Violence Prevention Act Part 9 s. 82 (3) (b)', NULL, 'establish criteria, conditions, requirements or obligations that must be met or complied with in relation to an exemption;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b2861798-2f82-4b56-a9a9-922b366dca7d', 'PAR', '56c7f834-9609-4bec-974b-bf79f283096c', 'c', 'Firearm Violence Prevention Act Part 9 s. 82 (3) (c)', NULL, 'specify how a person or entity may or must prove or establish that an exemption applies.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6253766a-fb30-4620-bc36-7e6cf2854e98', 'SEC', '06080d2b-cfdf-4254-9359-b66e766f0a0d', '83', 'Firearm Violence Prevention Act Part 9 s. 83', 'Regulations in relation to shooting ranges', NULL, 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d1d0afe9-04d3-46a5-8936-a55e825d32e8', 'SUBSEC', '6253766a-fb30-4620-bc36-7e6cf2854e98', '1', 'Firearm Violence Prevention Act Part 9 s. 83 (1)', NULL, 'For the purposes of section 30 (1) (a) and (b) [duty to require identification from shooting range user], the Lieutenant Governor in Council may make regulations respecting identification, including, without limitation, regulations that prescribe the following:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1b49e2e9-9a01-4e9e-b4db-ac3dcef26bf8', 'PAR', 'd1d0afe9-04d3-46a5-8936-a55e825d32e8', 'a', 'Firearm Violence Prevention Act Part 9 s. 83 (1) (a)', NULL, 'the form of identification that may or must be produced;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1fd9a28c-92da-4bb0-b70b-093463d14618', 'PAR', 'd1d0afe9-04d3-46a5-8936-a55e825d32e8', 'b', 'Firearm Violence Prevention Act Part 9 s. 83 (1) (b)', NULL, 'the manner in which identification may or must be produced.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('462c9967-948a-45d4-827f-07fcc06bb51a', 'SUBSEC', '6253766a-fb30-4620-bc36-7e6cf2854e98', '2', 'Firearm Violence Prevention Act Part 9 s. 83 (2)', NULL, 'For the purposes of section 30 (2), the Lieutenant Governor in Council may make regulations establishing full or partial exemptions in relation to a requirement under section 30 (1).', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('7243e440-7026-4597-a93e-02c00a5c0392', 'SUBSEC', '6253766a-fb30-4620-bc36-7e6cf2854e98', '3', 'Firearm Violence Prevention Act Part 9 s. 83 (3)', NULL, 'For the purposes of section 31 (3) [duty to require federal licence from shooting range user], the Lieutenant Governor in Council may make regulations establishing full or partial exemptions in relation to the requirement under section 31 (2).', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8b5443e1-05ed-404e-a32e-a8169e4354d7', 'SUBSEC', '6253766a-fb30-4620-bc36-7e6cf2854e98', '4', 'Firearm Violence Prevention Act Part 9 s. 83 (4)', NULL, 'A regulation under subsection (2) or (3) may do any of the following:', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
