  ('da31cb20-e767-4f30-9426-3eb512646f96', 'PAR', '8b5443e1-05ed-404e-a32e-a8169e4354d7', 'b', 'Firearm Violence Prevention Act Part 9 s. 83 (4) (b)', NULL, 'establish criteria, conditions, requirements or obligations that must be met or complied with in relation to an exemption;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0128c4cc-64d4-4579-a4f1-ea168ec07f2e', 'PAR', '8b5443e1-05ed-404e-a32e-a8169e4354d7', 'c', 'Firearm Violence Prevention Act Part 9 s. 83 (4) (c)', NULL, 'specify how a person or entity may or must prove or establish that an exemption applies.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('b49e207e-3269-4bea-88c1-9a6c49d068f5', 'SEC', '06080d2b-cfdf-4254-9359-b66e766f0a0d', '84', 'Firearm Violence Prevention Act Part 9 s. 84', 'Regulations in relation to motor vehicle impoundment', NULL, 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('5f73bce9-a14e-4d03-bdd7-568857ec1226', 'SUBSEC', 'b49e207e-3269-4bea-88c1-9a6c49d068f5', '1', 'Firearm Violence Prevention Act Part 9 s. 84 (1)', NULL, 'For the purposes of section 44 [request and order for release after impoundment period ends], the Lieutenant Governor in Council may make regulations as follows:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('03f6a79f-8f38-43f2-9559-0c03bb73414f', 'PAR', '5f73bce9-a14e-4d03-bdd7-568857ec1226', 'a', 'Firearm Violence Prevention Act Part 9 s. 84 (1) (a)', NULL, 'providing that section 44 does not apply;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
