  ('2a2b53fb-d368-4bd4-8b30-5c60f13abed6', 'PAR', '5f73bce9-a14e-4d03-bdd7-568857ec1226', 'c', 'Firearm Violence Prevention Act Part 9 s. 84 (1) (c)', NULL, 'authorizing the person who has custody of an impounded motor vehicle to release the motor vehicle, on request of the owner or a person authorized by the owner, after', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
