  ('dd1f5fbd-760e-4610-8582-4ba351fae18d', 'PAR', '6cdc4016-b466-4668-b6a5-5078c16ebdab', 'a', 'Firearm Violence Prevention Act Part 9 s. 85 (a)', NULL, 'specify purposes for which or circumstances in which an exemption applies;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('c47c8791-8592-464a-9768-47b5109c4a72', 'PAR', '6cdc4016-b466-4668-b6a5-5078c16ebdab', 'b', 'Firearm Violence Prevention Act Part 9 s. 85 (b)', NULL, 'establish criteria, conditions, requirements or obligations that must be met or complied with in relation to an exemption;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('24c5c9cc-4e68-4aef-8c42-b69bdef5e8ad', 'PAR', '6cdc4016-b466-4668-b6a5-5078c16ebdab', 'c', 'Firearm Violence Prevention Act Part 9 s. 85 (c)', NULL, 'specify how a person or entity may or must prove or establish that an exemption applies.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
