  ('2714e0fb-d400-45b0-a1c2-e99ca8581b47', 'DIV', '6637073d-8204-4b79-a46f-df83505847e9', '1', 'Firearm Violence Prevention Act Part 10 Division 1', 'Transitional Provision', NULL, 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
