  ('0c4c7373-7f31-4a29-afd7-f0f4a5466478', 'SUBSEC', '40d2ace4-9a4f-4c5d-9701-84a148ce8e22', '1', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1)', NULL, 'In this section:', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('68fe3238-5279-461b-8eb1-8e3c0496ecb5', 'DEF', '0c4c7373-7f31-4a29-afd7-f0f4a5466478', NULL, 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1)', 'effective date', '"effective date" means the date on which section 87 of this Act comes into force;', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('0fb0fc8c-210b-446c-8b2a-3ed9b8d41004', 'DEF', '0c4c7373-7f31-4a29-afd7-f0f4a5466478', NULL, 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1)', 'former Act', '"former Act" means the Firearm Act, R.S.B.C. 1996, c. 145;', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('361f407d-9300-4091-9892-983d27936fe1', 'DEF', '0c4c7373-7f31-4a29-afd7-f0f4a5466478', NULL, 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1)', 'pre-existing permit', '"pre-existing permit" means a permit under the Wildlife Act that', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1033e3c5-fcaf-41a8-9d1f-c788e062a122', 'PAR', '361f407d-9300-4091-9892-983d27936fe1', 'a', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1) (a)', NULL, 'exists immediately before the effective date, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('131c4148-2a73-4b23-aa59-be6716c673d4', 'PAR', '361f407d-9300-4091-9892-983d27936fe1', 'b', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (1) (b)', NULL, 'exempts a person from a requirement under section 9 (1) [offence] of the former Act.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('02215c25-b238-4641-b3c6-c79ef34cf5de', 'SUBSEC', '40d2ace4-9a4f-4c5d-9701-84a148ce8e22', '2', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (2)', NULL, 'A reference in a pre-existing permit to an exemption from a requirement under section 9 of the former Act is deemed to be a reference to an exemption from the corresponding requirement under any of the following provisions of this Act:', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('60969d96-d1a5-4ceb-9889-f3b378d4cd83', 'PAR', '02215c25-b238-4641-b3c6-c79ef34cf5de', 'a', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (2) (a)', NULL, 'section 4 [prohibition and requirement respecting firearm or imitation firearm in vehicle or boat];', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('43b0e944-64a6-4e74-8fb3-3766d3486d2b', 'PAR', '02215c25-b238-4641-b3c6-c79ef34cf5de', 'b', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (2) (b)', NULL, 'section 5 (1) [prohibition against discharging firearm from vehicle or boat].', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ba31687b-9271-491c-a44f-2eea1e184cdb', 'SUBSEC', '40d2ace4-9a4f-4c5d-9701-84a148ce8e22', '3', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (3)', NULL, 'Section 24 (8) (d) [suspension and cancellation of licences] of the Wildlife Act, as it read immediately before its repeal by section 96 of this Act, applies in respect of a person who', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('76998f1f-6a32-4dc1-83a0-e90d85a6b613', 'PAR', 'ba31687b-9271-491c-a44f-2eea1e184cdb', 'a', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (3) (a)', NULL, 'is alleged to have committed, before the effective date, an offence under section 3 [exercise of care for safety of others] of the former Act, and', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('71b3edbc-276b-421a-9937-a1332976a50c', 'PAR', 'ba31687b-9271-491c-a44f-2eea1e184cdb', 'b', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (3) (b)', NULL, 'is convicted, after the effective date, of the offence referred to in paragraph (a) of this subsection.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('a6785246-6d8d-48f1-a630-60a756b8ca49', 'SUBSEC', '40d2ace4-9a4f-4c5d-9701-84a148ce8e22', '4', 'Firearm Violence Prevention Act Part 10 Division 1 s. 86 (4)', NULL, 'Section 85 (1) (a) [failure to pay fine] of the Wildlife Act, as it read immediately before its amendment by section 98 of this Act, applies in respect of a person who, on the effective date, has not yet paid a fine imposed as a result of the person''s conviction, before the effective date, for an offence under the former Act.', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('aaf7035c-a72b-41fa-be28-cfb946a1499c', 'DIV', '6637073d-8204-4b79-a46f-df83505847e9', '2', 'Firearm Violence Prevention Act Part 10 Division 2', 'Repeal', NULL, 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('64c01d0b-1648-4484-853a-ec4a94a9d955', 'SEC', 'aaf7035c-a72b-41fa-be28-cfb946a1499c', '87', 'Firearm Violence Prevention Act Part 10 Division 2 s. 87', 'Repeal of Firearm Act', 'The Firearm Act, R.S.B.C. 1996, c. 145, is repealed.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d406f575-2760-43b2-96ca-b18fed85ff91', 'DIV', '6637073d-8204-4b79-a46f-df83505847e9', '3', 'Firearm Violence Prevention Act Part 10 Division 3', 'Consequential, Related and Minor Amendments', NULL, 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d8e57407-7000-4903-8d13-162b34cebb8f', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '88', 'Firearm Violence Prevention Act Part 10 Division 3 s. 88', 'Armoured Vehicle and After-Market Compartment Control Act', 'Section 1 of the Armoured Vehicle and After-Market Compartment Control Act, S.B.C. 2010, c. 8, is amended in the definition of "after-market compartment" by striking out "and" at the end of paragraph (a), by adding ", and" at the end of paragraph (b) and by adding the following paragraph:<br/>(c) conceals, hides or otherwise prevents the discovery of the contents of the compartment;.', 1, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('8c4a8c5d-547c-4bee-9674-4bcf8dc7f239', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '89', 'Firearm Violence Prevention Act Part 10 Division 3 s. 89', 'Armoured Vehicle and After-Market Compartment Control Act', 'Section 3 is amended<br/>(a) by repealing subsection (2) (b) and substituting the following:<br/>(b) include authorizations for the registrar to<br/>(i) carry out the prescribed checks regarding the applicant or permit holder, and<br/>(ii) collect and use the applicant''s or permit holder''s fingerprints to verify the results of the prescribed checks, and, and<br/>(b) by adding the following subsection:<br/>(2.1) If an applicant for an armoured vehicle permit or renewal of an armoured vehicle permit is not an individual, the application must include authorizations for the registrar to carry out the actions described in subsection (2) (b) (i) and (ii) in relation to one or more individuals who are any of the following, as specified by the registrar:<br/>(a) an owner of the applicant;<br/>(b) a manager of the applicant;<br/>(c) one or more other individuals who the registrar considers control or direct the applicant.', 2, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('fd7e27cc-757c-498d-aa84-58ce5cac5834', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '90', 'Firearm Violence Prevention Act Part 10 Division 3 s. 90', 'Armoured Vehicle and After-Market Compartment Control Act', 'Section 7 (2) and (3) is repealed and the following substituted:<br/>(2) A person must not install, alter or repair an after-market compartment in a vehicle.<br/>(3) Subsection (1) does not apply in respect of a person who owns, operates or uses a vehicle that contains an after-market compartment if any of the following apply:<br/>(a) the vehicle is operated or used by a peace officer in the exercise of the peace officer''s powers or performance of the peace officer''s duties;<br/>(b) the after-market compartment is in a vehicle that is forfeited to the government and the government owns, operates or uses the vehicle;<br/>(c) the owner of the vehicle is exempt from that subsection under the regulations.<br/>(4) Subsection (2) does not apply in respect of a person who installs, alters or repairs an after-market compartment in a vehicle if any of the following apply:<br/>(a) the vehicle is operated or used by a peace officer in the exercise of the peace officer''s powers or performance of the peace officer''s duties;<br/>(b) the after-market compartment is in a vehicle that is forfeited to the government and the government owns, operates or uses the vehicle;<br/>(c) the person is exempt from that subsection under the regulations.', 3, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('ac7f0a8c-e390-49a9-99e5-25c723b88ae5', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '91', 'Firearm Violence Prevention Act Part 10 Division 3 s. 91', 'Armoured Vehicle and After-Market Compartment Control Act', 'Section 20 (2) is amended<br/>(a) in paragraph (g) by striking out "a class of persons" and substituting "a class of persons or the government", and<br/>(b) in paragraph (h) by striking out "proof of an exemption referred to in section 7 (3)" and substituting "proof of an exemption under section 7 (3) or (4)".', 4, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('584fbe5b-0ffc-4ae4-8d49-652fc5304877', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '92', 'Firearm Violence Prevention Act Part 10 Division 3 s. 92', 'Body Armour Control Act', 'Section 4 (2) (b) of the Body Armour Control Act, S.B.C. 2009, c. 24, is repealed and the following substituted:<br/>(b) include authorizations for the registrar to<br/>(i) carry out the prescribed checks regarding the applicant or permit holder, and<br/>(ii) collect and use the applicant''s or permit holder''s fingerprints to verify the results of the prescribed checks, and.', 5, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4af43805-6b13-4d1d-b826-57a1055ff5a7', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '93', 'Firearm Violence Prevention Act Part 10 Division 3 s. 93', 'Motor Vehicle Act', 'Section 26 of the Motor Vehicle Act, R.S.B.C. 1996, c. 318, is amended<br/>(a) in subsection (1) by striking out "or" at the end of paragraph (h), by adding ", or" at the end of paragraph (i) and by adding the following paragraph:<br/>(j) was the owner of a motor vehicle at the time it was impounded under section 35 or 36 of the Firearm Violence Prevention Act if, under section 48 (1) of that Act, the Insurance Corporation of British Columbia is directed to refuse the issuance.,<br/>(b) in subsection (2) by striking out "or" at the end of paragraph (d.1), by adding ", or" at the end of paragraph (e) and by adding the following paragraph:<br/>(f) was the owner of a motor vehicle at the time it was impounded under section 35 or 36 of the Firearm Violence Prevention Act if, under section 48 (1) of that Act, the Insurance Corporation of British Columbia is directed to refuse the issuance., and<br/>(c) in subsection (3) by striking out "or" at the end of paragraph (c).', 6, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('e23e6ca9-0726-4723-9123-707fee78e907', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '94', 'Firearm Violence Prevention Act Part 10 Division 3 s. 94', 'Motor Vehicle Act', 'Section 83 (2) (c) is repealed and the following substituted:<br/>(c) section 3, 4 or 5 (1) of the Firearm Violence Prevention Act,.', 7, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6e6b802e-9f8e-453d-be94-5413cbc24a33', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '95', 'Firearm Violence Prevention Act Part 10 Division 3 s. 95', 'Wildlife Act', 'Section 19 (3) of the Wildlife Act, R.S.B.C. 1996, c. 488, is repealed and the following substituted:<br/>(3) If a regional manager issues a permit respecting the use of firearms, the regional manager may<br/>(a) exempt a person from section 4 or 5 (1), in whole or in part, of the Firearm Violence Prevention Act, and<br/>(b) specify the conveyance or type of conveyance to which the permit is limited.', 8, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('312e891c-d30d-44b0-8d44-23d66743ecf0', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '96', 'Firearm Violence Prevention Act Part 10 Division 3 s. 96', 'Wildlife Act', 'Section 24 (8) is amended by adding "or" at the end of paragraph (c) and by repealing paragraph (d).', 9, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('2dbcba64-e8e1-4f04-811f-1241b64ef925', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '97', 'Firearm Violence Prevention Act Part 10 Division 3 s. 97', 'Wildlife Act', 'Section 84 is amended<br/>(a) in subsections (6.2) and (6.3) by striking out "under this Act or the Firearm Act" and substituting "under this Act", and<br/>(b) in subsections (6.2) (a) and (6.3) (b) by striking out "this Act, the Firearm Act or their regulations" and substituting "this Act or the regulations".', 10, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('6a89260b-82b6-4aad-9c60-ef1bce9f946d', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '98', 'Firearm Violence Prevention Act Part 10 Division 3 s. 98', 'Wildlife Act', 'Section 85 (1) (a) is repealed and the following substituted:<br/>(a) fails to pay, within the time required by law, a fine imposed as a result of the person''s conviction for an offence under<br/>(i) this Act, or<br/>(ii) a prescribed provision of the Firearm Violence Prevention Act, and.', 11, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('d0a82975-e5b2-422e-a247-326334b307e0', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '99', 'Firearm Violence Prevention Act Part 10 Division 3 s. 99', 'Wildlife Act', 'Section 86 is amended by striking out "and section 9 of the Firearm Act".', 12, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('1943aa57-67ac-4b92-b59c-477294312ec6', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '100', 'Firearm Violence Prevention Act Part 10 Division 3 s. 100', 'Wildlife Act', 'Sections 90 (1) and (2), 98 and 98.1 (1) (a) are amended by striking out "or the Firearm Act".', 13, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('9a0112f6-7e35-4e7b-9ae8-b38045e1e3d4', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '101', 'Firearm Violence Prevention Act Part 10 Division 3 s. 101', 'Wildlife Act', 'Section 108 (3) is amended by adding the following paragraph:<br/>(d.1) in respect of a regulation under paragraph (d) of this subsection, exempting a person from section 4 or 5 (1), in whole or in part, of the Firearm Violence Prevention Act;.', 14, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP),
  ('4dafb840-7bed-47cc-b44c-b62f48379f17', 'SEC', 'd406f575-2760-43b2-96ca-b18fed85ff91', '102', 'Firearm Violence Prevention Act Part 10 Division 3 s. 102', 'Commencement', 'This Act comes into force by regulation of the Lieutenant Governor in Council.', 15, '1a208941-c34b-4d38-add2-ae4229410360', 'system', CURRENT_TIMESTAMP);

